INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('privacy-policy','Privacy Policy','Who we are and what this covers: Simal Technologies Middle East LLC (Bur Dubai, PO 49740) is the data controller for this platform.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('terms-conditions','Terms & Conditions','Using the platform: RFQ submissions, account use and content licensing; quotes are valid 7 days unless stated otherwise.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('cookie-policy','Cookie Policy','Cookies we set: Session (sign-in), preference (language, dismissed announcements) and analytics cookies with consent gating.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('return-policy','Return Policy','Returns & RMA: Authorized-line products carry manufacturer warranty; RMA handled locally with the Simal desk (see product page).
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('shipping-policy','Shipping Policy','Delivery: UAE same/next business day from JAFZA; GCC same week; tracking issued per consignment.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('refund-policy','Refund Policy','Refunds: Pre-payment refunds processed within 10 business days to the original instrument after RMA acceptance.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('accessibility-statement','Accessibility Statement','Our commitment: Target WCAG 2.1 AA: contrast-verified palette, keyboard operability, RTL parity — issues welcome via contact.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('privacy-policy','سياسة الخصوصية','من نحن وما تغطيه هذه السياسة: شركة سيمال تكنولوجيز الشرق الأوسط ش.ذ.م.م (بر دبي، ص.ب 49740) هي الجهة المسؤولة عن معالجة البيانات لهذه المنصة.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('terms-conditions','الشروط والأحكام','استخدام المنصة: تقديم طلبات عروض الأسعار (RFQ)، واستخدام الحسابات وترخيص المحتوى. عروض الأسعار صالحة لمدة 7 أيام ما لم يذكر خلاف ذلك.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('cookie-policy','سياسة ملفات تعريف الارتباط','ملفات تعريف الارتباط التي نستخدمها: ملفات تعريف الارتباط الضرورية للجلسة وتسجيل الدخول، وملفات التفضيلات (اللغة والإشعارات)، وملفات التحليلات المشروطة بموافقة المستخدم المسبقة.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('return-policy','سياسة الإرجاع والضمان','الإرجاع وخدمات RMA: تحمل جميع منتجات العلامات التجارية المعتمدة ضمان الشركة المصنعة الرسمي، وتتم إدارة طلبات الصيانة والإرجاع محلياً عبر مكتب سيمال المعتمد في دبي.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('shipping-policy','سياسة الشحن والتسليم','التسليم: شحن خلال نفس اليوم أو يوم العمل التالي داخل دولة الإمارات من مركزنا اللوجستي في المنطقة الحرة بجبل علي (جافزا)؛ وخلال نفس الأسبوع لدول مجلس التعاون الخليجي.
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('refund-policy','سياسة الاسترداد','الاسترداد المالي: تتم معالجة عمليات استرداد المبالغ المدفوعة مسبقاً خلال 10 أيام عمل إلى وسيلة الدفع الأصلية بعد الموافقة النهائية على طلب الإرجاع (RMA).','ar',1) ON CONFLICT (slug, lang) DO NOTHING;
INSERT INTO legal_policies (slug,title,body,lang,version) VALUES ('accessibility-statement','بيان إمكانية الوصول الرقمي','التزامنا بإمكانية الوصول: نلتزم بتطبيق معايير WCAG 2.2 بالمستوى AA، بما في ذلك تباين الألوان المعتمد، والتنقل الكامل عبر لوحة المفاتيح، والدعم الكامل للنصوص من اليمين إلى اليسار (RTL) للغة العربية. نرحب بأي ملاحظات عبر صفحة الاتصال.','ar',1) ON CONFLICT (slug, lang) DO NOTHING;
