INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','finance','en','{"id":"finance","icon":"💰","name":"Finance & Accounting","tag":"Complete financial control. From day one.","overview":"A complete, real-time view of your financial position — from general ledger and accounts receivable/payable to multi-currency consolidation and tax compliance. Built on Odoo 19 CE and enhanced with UniVAT.","caps":[["General Ledger",["Customizable multi-level chart of accounts","Journal entries with approval workflows","Multi-company consolidation","Immutable audit trail"]],["Accounts Receivable",["Automated invoices from sales orders with VAT","Aging reports with automated dunning","Credit limits, holds and risk assessment"]],["Accounts Payable",["Vendor bills with automatic tax calculation","Batch payment proposals with approvals","Expense management and GR/IR matching"]],["Bank & Cash",["Automated reconciliation (CSV, OFX, CAMT)","Multi-bank, multi-currency accounts","Predictive cash-flow forecasting"]],["Financial Reporting",["Balance sheet, P&L, cash-flow with drill-down","Trial balance with variance analysis","Tax report ready for authority submission","Budget vs. actual variance"]]],"why":["Real-time position across entities and currencies","UniVAT integration for compliant tax handling","Audit-ready from the first journal entry"],"related":["univat","crm","inventory"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','hr','en','{"id":"hr","icon":"👥","name":"HR & Payroll","tag":"Manage your most valuable asset — your people.","overview":"Employee records, contracts, attendance and WPS-compliant payroll in one system — with UAE labor law compliance built in and employee self-service that ends the spreadsheet era.","caps":[["Employee Database",["Records, contracts, documents, org structure"]],["Recruitment & Onboarding",["Job postings, applicant tracking, onboarding flows"]],["Attendance & Time Tracking",["Shifts, biometric integration, overtime rules"]],["Leave Management",["Leave types, accruals, approval workflows"]],["Payroll Processing",["WPS-compliant runs, allowances, deductions, end-of-service"]],["Performance & Training",["Appraisals, goals, training records"]]],"why":["One system, no spreadsheets","UAE labor law built in","Employee self-service portal"],"related":["projects","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','crm','en','{"id":"crm","icon":"📈","name":"Sales & CRM","tag":"Turn leads into loyal customers.","overview":"Pipeline, quotations, sales orders and a full customer 360 — fully integrated with inventory and finance so every quote reflects real stock and real margins.","caps":[["Lead Management",["Capture, qualify, assign and track every lead"]],["Opportunity Pipeline",["Stages, probabilities, forecast by close date"]],["Quotation Management",["Templates, versioning, e-signature-ready PDFs"]],["Sales Order Processing",["Order to invoice, backorders, drop-ship"]],["Customer Database",["Contacts, history, activities, customer 360"]],["Dashboard & Reports",["Win/loss, funnel velocity, rep performance"]]],"why":["Full integration with stock and ledgers","No per-user CRM fees — $0 licensing","Mobile-ready for field teams"],"related":["inventory","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','inventory','en','{"id":"inventory","icon":"📦","name":"Inventory & Supply Chain","tag":"Complete visibility. From warehouse to delivery.","overview":"Multi-warehouse stock, purchasing and supplier management with barcode support — the same engine Simal runs for its own distribution operations.","caps":[["Stock Management",["Real-time levels, valuation (FIFO/AVCO), cycle counts"]],["Purchase Management",["RFQs, approvals, vendor bills, GR/IR"]],["Warehouse Management",["Locations, putaway, picking strategies"]],["Barcode Integration",["Scanning for receiving, picking, inventory"]],["Multi-Location Inventory",["Across warehouses, stores and consignment"]],["Supplier Management",["Vendor records, price lists, performance"]]],"why":["End-to-end integration with sales and finance","Real-time accuracy over spreadsheets","Cost control with full traceability"],"related":["crm","manufacturing"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','manufacturing','en','{"id":"manufacturing","icon":"🏭","name":"Manufacturing","tag":"From raw materials to finished products. Effortlessly.","overview":"BOM, MRP and work-order control with shop-floor tracking and real-time costing — sized for the RMG, pharma and food plants the team has implemented for.","caps":[["Bill of Materials (BOM)",["Multi-level BOMs, variants, engineering changes"]],["Material Requirements Planning",["Auto-generated procurement proposals"]],["Work Order Management",["Routing, operations, scheduling"]],["Quality Control",["Checkpoints, failure analysis, certificates"]],["Shop Floor Tracking",["Operator, machine and time capture"]],["Costing",["Actual vs. standard, work-center rates"]]],"why":["Plan production from real demand","Quality built into every stage","Know true product cost as you build"],"related":["inventory","projects"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','projects','en','{"id":"projects","icon":"✅","name":"Project Management","tag":"Deliver every project on time and on budget.","overview":"Planning, resourcing, tasks and timesheets with budget control — and client billing plus real-time profitability per project straight from the ledgers.","caps":[["Project Planning",["Phases, milestones, dependencies, Gantt"]],["Resource Allocation",["People, skills and workload balancing"]],["Task Management",["Kanban, assignments, deadlines"]],["Time Tracking",["Timesheets, approvals, billable flags"]],["Budget & Financials",["Budget vs. actual, committed costs"]]],"why":["Integrated financials — no double entry","Client billing from approved timesheets","Real-time profitability per project"],"related":["hr","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_module','univat','en','{"id":"univat","icon":"🧾","name":"UniVAT & e-invoicing","tag":"Compliant VAT automation — NBR-approved, Peppol-ready.","overview":"One of only five NBR-approved VAT systems in Bangladesh, with direct government-system integration — and Peppol-ready UAE e-invoicing tooling for the 1 Jan 2027 mandate.","caps":[["Tax Automation",["VAT calculation on every transaction","Automated returns and submissions"]],["NBR Compliance",["Direct integration with government systems","Approved for Bangladesh VAT taxpayers"]],["UAE Peppol Readiness",["E-invoicing tooling ahead of the 2027 mandate","Structured invoice data, ready for ASP onboarding"]],["Audit & Trail",["Every tax event logged and reportable"]]],"why":["Compliance without custom builds","Same platform as the rest of UniERP","Regional rollout path: Dhaka today, Dubai 2027"],"related":["finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','custom-dev','en','{"id":"custom-dev","name":"Custom Software Development","overview":"Bespoke software engineered to your exact workflows — web applications, enterprise systems and API layers. Off-the-shelf forces you to adapt to the software; custom adapts to you, and you own the source code (content §06-16).","how":[["1 · Discovery","Requirements workshops, success criteria, fixed or agile scope"],["2 · Build","Two-week sprints with demos; 40+ engineers across web, mobile and API"],["3 · Own it","Source code handover, documentation, AMC support via Simal"]],"faq":[["Custom vs off-the-shelf — how do we decide?","We model both over five years, including workarounds you accept with off-the-shelf. If package software fits, we will say so — we also implement UniERP."],["Who owns the source code?","You do, from final acceptance — a founding principle of this practice (content §06-16)."]],"subs":[{"id":"web-apps","name":"Web Applications","what":"Browser-based business applications — portals, dashboards, internal tools — built on modern frameworks and hosted where you choose.","gives":["Working product in sprints, not months","Responsive UI usable on any device","Admin roles, audit logs, SSO options"],"stack":["React / Vue front-ends","Node / Python services","PostgreSQL / MySQL"]},{"id":"enterprise-systems","name":"Enterprise Systems","what":"Core-of-business systems that replace spreadsheet pipelines — order management, workflows, integrations between your ERP, CRM and finance.","gives":["One source of truth across departments","Automated approvals and escalation","Integration with UniERP and third parties"],"stack":["Service-oriented architecture","Message queues for reliability","Role-based access control"]},{"id":"api-development","name":"API Development","what":"Contract-first APIs that connect your systems and let partners integrate cleanly — documented, versioned, monitored.","gives":["OpenAPI-documented endpoints","Versioned releases without breaking consumers","Keys, quotas and usage analytics"],"stack":["REST / GraphQL","OAuth 2.0 / JWT","API gateways"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','cloud','en','{"id":"cloud","name":"Cloud Services & Infrastructure","overview":"Cloud computing for scalability, cost optimization and innovation — migration, CI/CD pipelines and infrastructure run by certified engineers with 24/7 coverage (content §06-17).","how":[["1 · Assess","Workload inventory, cost baseline, target architecture"],["2 · Migrate","Lift-and-shift or re-platform, cutover with rollback plans"],["3 · Operate","Monitoring, FinOps reviews, reserved-capacity savings"]],"faq":[["Will our bill actually go down in the cloud?","Usually after right-sizing and reserved capacity — we baseline your current cost first and report savings against it, monthly."],["Can you run a cloud we already chose?","Yes — AWS, Azure and GCP are all house-standard; we meet you where you are."]],"subs":[{"id":"cloud-migration","name":"Cloud Migration","what":"Moving workloads from on-premise to AWS/Azure/GCP or between clouds — with data integrity checks and zero-surprise cutover.","gives":["Migration runbook and rollback plan","Right-sized instances from day one","Post-migration performance baseline"],"stack":["AWS / Azure / GCP","Landing-zone patterns","Database replication"]},{"id":"cicd","name":"CI/CD Pipelines","what":"Automated build-test-deploy pipelines so releases ship in minutes with regressions caught before production.","gives":["Pipeline as code in your repo","Staging environment mirroring production","Deployment gates and approvals"],"stack":["GitHub Actions / GitLab CI","Docker containers","Blue-green deployments"]},{"id":"infra","name":"Cloud Infrastructure","what":"Design and operation of cloud foundations — networks, identity, security groups, backups — as maintainable code.","gives":["Infrastructure-as-code repository","Cost dashboards and budgets","Disaster-recovery runbooks"],"stack":["Terraform / Pulumi","Kubernetes where it earns its keep","Monitoring and alerting stacks"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','cybersecurity','en','{"id":"cybersecurity","name":"Cybersecurity Services","overview":"Enterprise-grade protection from evolving threats — audits, penetration testing and compliance programs that keep attackers out and auditors satisfied.","how":[["1 · Baseline","Asset inventory, external scan, risk register"],["2 · Test & fix","Pen-test, remediation sprint with your team"],["3 · Comply","Evidence packs for ISO 27001 / SOC 2 / client audits"]],"faq":[["How often should we pen-test?","At minimum annually and after any major release — regulators and enterprise clients increasingly expect both."],["Do you fix what you find?","Yes — every engagement includes a remediation option with your team or ours, then a re-test that proves the fix."]],"subs":[{"id":"security-audit","name":"Security Audits","what":"Systematic review of applications, infrastructure and processes against recognized controls, with a prioritized fix list.","gives":["Executive risk report","Technical findings with severity ranks","90-day remediation roadmap"],"stack":["OWASP Top 10","CIS benchmarks","ISO 27001 controls"]},{"id":"pentest","name":"Penetration Testing","what":"Simulated attacks on your applications and networks by engineers who think like intruders — web, network and social vectors.","gives":["Exploit proof-of-concepts","Re-test after fixes","Board-ready summary"],"stack":["Kali toolchain","Custom exploit development","Phishing simulation"]},{"id":"compliance","name":"Compliance","what":"Turning security work into audit evidence — policy authoring, control mapping, internal audits for client and regulatory demands.","gives":["Policy and procedure set","Control-to-evidence matrix","Internal audit and gap reports"],"stack":["ISO 27001 / SOC 2","PDPL / GDPR alignment","Vendor risk templates"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','digital-transform','en','{"id":"digital-transform","name":"Digital Transformation","overview":"Reimagining business processes, culture and customer experience through strategic digital transformation — from paper to platform, from legacy to modern.","how":[["1 · Map","Current-state process capture with the people who run it"],["2 · Redesign","To-be processes, automation candidates, ROI model"],["3 · Land","Pilot, measure, scale — with change-management support"]],"faq":[["How long does a transformation programme take?","First measurable wins inside a quarter; full programmes run 6–18 months depending on scope — we pilot before we scale."],["Will our people adopt the change?","That is the job, not an afterthought — pilots include the teams who run the process, and training is part of every stage."]],"subs":[{"id":"process-automation","name":"Process Automation","what":"Replacing repetitive manual work — approvals, data entry, report assembly — with reliable automated flows.","gives":["Process time-and-cost baseline vs after","Bots/workflows with exception handling","Handover documentation"],"stack":["Workflow engines","RPA where fit","Document OCR"]},{"id":"legacy-modernization","name":"Legacy Modernization","what":"Bringing ageing systems forward — strangler-pattern migrations that retire risk without big-bang rewrites.","gives":["Legacy assessment and risk map","Incremental migration plan","Zero-downtime cutover approach"],"stack":["Strangler-fig pattern","Data migration tooling","Compatibility layers"]},{"id":"dx-strategy","name":"Transformation Strategy","what":"A sequenced roadmap tying technology initiatives to business outcomes — what to do first, and what not to do yet.","gives":["Capability assessment","Prioritized initiative roadmap","Business-case per initiative"],"stack":["Value-stream mapping","OKR frameworks","Build-vs-buy analysis"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','aiml','en','{"id":"aiml","name":"Artificial Intelligence & Machine Learning","overview":"Practical AI that solves real problems and delivers tangible returns — machine learning, business intelligence and predictive analytics built by a team shipping AI in production since before it was fashionable (content §06-18).","how":[["1 · Use case","Pick problems worth solving — ranked by ROI, feasibility and data readiness"],["2 · Prove","A working model on your data in weeks, not quarters"],["3 · Productionize","Deployed, monitored, explained — with retraining built in"]],"faq":[["How much data do we need to start an AI project?","Less than most teams fear — for forecasting or classification, a few thousand historical rows often suffices for a first proving model; we assess data readiness in the discovery call."],["Do we own the models you build?","Yes — models, code and documentation are yours. Nothing is held hostage to a subscription."]],"subs":[{"id":"ml","name":"Machine Learning","what":"Custom models for forecasting, classification, recommendation and anomaly detection — trained on your data, owned by you.","gives":["Model with measured accuracy on your data","Feature pipeline in production","Retraining cadence and monitoring"],"stack":["Python / scikit-learn / XGBoost","PyTorch for deep learning","MLOps pipelines"]},{"id":"bi","name":"Business Intelligence","what":"Dashboards and reporting that answer business questions in seconds — one semantic layer over all your systems.","gives":["Executive and operational dashboards","Self-service training for your team","Scheduled reports and alerts"],"stack":["Power BI / Metabase / Superset","SQL semantic layer","ETL/ELT pipelines"]},{"id":"predictive","name":"Predictive Analytics","what":"Tomorrow''s numbers today — demand forecasts, churn scoring, risk ranking that change decisions before events happen.","gives":["Forecast with confidence intervals","Churn/risk scores wired into CRM","Backtesting against history"],"stack":["Time-series models","Gradient-boosted ranking","Champion-challenger testing"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','consultancy','en','{"id":"consultancy","name":"IT Consultancy & Advisory","overview":"Expert advisory for optimal technology decisions and strategic IT alignment — senior architects who have shipped, not just slideware.","how":[["1 · Listen","Business goals, constraints, existing estate — documented"],["2 · Advise","Options with trade-offs, costs and risks — in writing"],["3 · Anchor","Stay on call through vendor selection and delivery"]],"faq":[["Are you vendor-neutral?","Yes — advice is scoped to your goals, and where a Simal product fits we say so explicitly; where it does not, we say that too."],["What does an engagement look like?","Typically a 2–4 week assessment producing written recommendations, then optional anchor support through delivery."]],"subs":[{"id":"tech-strategy","name":"Technology Strategy","what":"A 12–24 month technology plan that matches ambition to budget and team reality.","gives":["Current-state assessment","Target architecture and roadmap","Quarterly milestone plan"],"stack":["Architecture reviews","TCO modeling","Skills-gap analysis"]},{"id":"arch-review","name":"Architecture Review","what":"Independent review of a system or design before you commit — catching the expensive mistakes early.","gives":["Findings on scalability/security/maintainability","Concrete refactoring recommendations","Risk register"],"stack":["ADR documentation","Threat modeling","Performance profiling"]},{"id":"vendor-selection","name":"Vendor Selection","what":"Structured evaluation of platforms and suppliers — requirements, scoring, negotiation support.","gives":["Weighted requirements matrix","Demos scripted to your use cases","Contract and SLA checklist"],"stack":["RFP templates","Proof-of-concept scoring","Reference-check frameworks"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','pm','en','{"id":"pm","name":"Project Management","overview":"On-time, on-budget delivery with full transparency — dedicated project managers, agile coaching and PMO setup that keep programmes honest.","how":[["1 · Plan","Scope, RAID log, communication cadence agreed up front"],["2 · Track","Weekly status with earned value and risk deltas"],["3 · Deliver","Acceptance criteria met, lessons captured"]],"faq":[["Can you rescue a project that is already late?","Yes — recovery starts with an honest re-baseline: what is done, what is left, what it truly takes; then a re-plan your stakeholders can trust."],["Do you work with our internal PMs?","Regularly — dedicated PM leading, or coaching your PMs to lead while we assure the method."]],"subs":[{"id":"dedicated-pm","name":"Dedicated Project Management","what":"A named PM running your delivery end-to-end — schedule, budget, vendors, stakeholders.","gives":["Single point of accountability","Weekly status and RAID management","Delivery metrics dashboard"],"stack":["PRINCE2 / PMI methods","Jira / Monday boards","Earned-value tracking"]},{"id":"agile-coaching","name":"Agile Coaching","what":"Leveling up your in-house teams — ceremonies, estimation, backlog hygiene — by coaches who run agile daily.","gives":["Team assessment and playbook","Sprint mechanics installed","Velocity and quality metrics"],"stack":["Scrum / Kanban","Story-mapping workshops","Definition-of-done frameworks"]},{"id":"pmo-setup","name":"PMO Setup","what":"A project management office for organizations running many initiatives — standards, templates, reporting lines.","gives":["PMO charter and standards pack","Portfolio dashboard","Gate review process"],"stack":["Stage-gate governance","Portfolio prioritization","Resource planning"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','devops','en','{"id":"devops","name":"DevOps & Infrastructure Management","overview":"Automated infrastructure and application deployment for faster, more reliable releases — the discipline behind shipping weekly instead of quarterly.","how":[["1 · Automate","Builds, tests, deployments out of human hands"],["2 · Monitor","Golden signals, alerting that respects on-call sleep"],["3 · Improve","Post-incident reviews, capacity planning, cost tuning"]],"faq":[["Do we need to rewrite everything to get CI/CD?","No — pipelines wrap the code you have; containerization can come later, one service at a time."],["Who fixes the pipeline at 2am?","The monitoring we install alerts before users notice, with runbooks your team or our 24/7 desk can execute."]],"subs":[{"id":"cicd-devops","name":"CI/CD Engineering","what":"Pipeline design and implementation across your repos — from commit to production with quality gates.","gives":["Trunk-based pipeline with gates","Artifact and release management","Rollback in one command"],"stack":["GitLab CI / Jenkins","Container registries","Feature flags"]},{"id":"iac","name":"Infrastructure as Code","what":"Servers, networks and policies defined in code — reviewable, repeatable, restorable.","gives":["Terraform modules for your estate","Environment parity dev=prod","Drift detection"],"stack":["Terraform / Ansible","CloudFormation where AWS-native","Secrets management"]},{"id":"monitoring","name":"Monitoring & Observability","what":"Knowing before your customers do — metrics, logs and traces correlated into actionable alerts.","gives":["Golden-signal dashboards","Alert runbooks per service","SLOs with error budgets"],"stack":["Prometheus / Grafana","ELK / Loki logging","Distributed tracing"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','qa','en','{"id":"qa","name":"Quality Assurance & Testing","overview":"Industry-leading quality metrics through systematic testing — manual depth where it matters, automation everywhere else.","how":[["1 · Strategy","Risk-based test plan aligned to release cadence"],["2 · Execute","Functional, regression, performance, security checks"],["3 · Report","Defect analytics that steer the next sprint"]],"faq":[["Manual or automated — which do we need?","Both, in the right ratio: automation for regression, humans for exploration. We start manual where it is cheapest to find bugs, then automate what keeps breaking."],["When can you start?","Typically within two weeks — a test strategy workshop first, then coverage grows sprint by sprint."]],"subs":[{"id":"manual-testing","name":"Manual Testing","what":"Human exploratory testing that finds what scripts can''t — usability, edge cases, real-world flows.","gives":["Test cases mapped to requirements","Exploratory session reports","Release go/no-go recommendation"],"stack":["Test-case management","Cross-device matrices","Accessibility checks"]},{"id":"test-automation","name":"Test Automation","what":"Regression suites that run on every commit — UI, API and unit layers maintained as code.","gives":["Automated smoke + regression packs","CI-integrated execution","Flake-free suite maintenance"],"stack":["Playwright / Cypress","REST-assured API tests","Parallel execution grids"]},{"id":"perf-testing","name":"Performance Testing","what":"Load, stress and soak testing that tells you where the system bends — before your peak season does.","gives":["Bottleneck analysis with fixes","Capacity numbers per tier","Load-test scripts you can rerun"],"stack":["k6 / JMeter","APM correlation","Cloud load generators"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','uiux','en','{"id":"uiux","name":"UI/UX Design","overview":"Design experiences that delight users and drive business results — research-backed interfaces for web, mobile and internal tools.","how":[["1 · Research","Users interviewed, journeys mapped, assumptions tested"],["2 · Design","Wireframes to hi-fi prototypes, design system included"],["3 · Validate","Usability tests before a line of code is written"]],"faq":[["Can you work with our existing brand?","Always — design systems extend your brand; we document tokens so future screens stay consistent."],["How do you test designs before build?","Clickable prototypes with real users — findings are prioritized and the winning flow goes to development."]],"subs":[{"id":"design-systems","name":"Design Systems","what":"Reusable component libraries and tokens that keep every screen consistent and every future screen faster.","gives":["Component library in Figma + code","Usage guidelines and do/don''ts","Governance for new components"],"stack":["Figma libraries","Storybook","Design tokens"]},{"id":"prototyping","name":"Prototyping & Testing","what":"Clickable prototypes tested with real users — validation before build cost is incurred.","gives":["Hi-fi interactive prototype","Usability findings with severity","Iteration on the winning flow"],"stack":["Figma prototypes","Moderated test sessions","Heatmap analytics"]},{"id":"ux-research","name":"UX Research","what":"Evidence instead of opinion — user interviews, analytics reviews and journey maps that settle design debates.","gives":["Persona and journey artifacts","Prioritized pain-point list","Recommendations traceable to evidence"],"stack":["Interview scripts","Analytics funnels","Card sorting"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','mobile','en','{"id":"mobile","name":"Mobile App Development","overview":"Powerful mobile apps that engage users and drive growth — native and cross-platform, from concept to app-store delivery.","how":[["1 · Define","Core journeys, platform choice, offline behavior decided"],["2 · Build","Cross-platform first, native where it counts"],["3 · Ship","Store submission, review handling, release trains"]],"faq":[["Native or cross-platform?","Cross-platform (Flutter/React Native) first for reach and speed; native modules where cameras, biometrics or background work demand it."],["Do you handle store review rejections?","Yes — store delivery is part of the service: listings, phased releases and the rejection playbook."]],"subs":[{"id":"ios-android","name":"iOS & Android Development","what":"Native applications that use each platform''s capabilities fully — cameras, biometrics, background sync.","gives":["Platform-native performance","App-store compliance handled","Crash-free rate targets"],"stack":["Swift / Kotlin","Platform design guidelines","Crash and ANR monitoring"]},{"id":"cross-platform","name":"Cross-Platform Apps","what":"One codebase, two stores — Flutter and React Native apps that feel native and ship faster.","gives":["Single team velocity","Shared business logic with web","Over-the-air update capability"],"stack":["Flutter / React Native","Shared design system","CodePush OTA"]},{"id":"app-delivery","name":"App Store Delivery","what":"The unglamorous half of mobile — store listings, phased releases, review rejections resolved.","gives":["Store assets and ASO copy","Phased rollout plan","Rejection-handling playbook"],"stack":["App Store / Play consoles","CI build pipelines","Release automation"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_service','data-bi','en','{"id":"data-bi","name":"Data Analytics & Business Intelligence","overview":"Unlock the power of your data with advanced analytics — pipelines, warehouses and business intelligence that turn records into decisions.","how":[["1 · Model","Data sources inventoried, warehouse schema designed"],["2 · Pipe","Automated ingestion with quality checks"],["3 · Decide","Dashboards, alerts and ML-ready datasets"]],"faq":[["Our data is a mess — can we still do BI?","Yes, and you are typical — pipelines include cleaning and quality checks; the warehouse becomes the place clean data lives."],["Which BI tool should we pick?","We are tool-neutral: Metabase where cost matters, Power BI inside Microsoft estates — we model the data so either works."]],"subs":[{"id":"warehouse","name":"Data Warehousing","what":"A single, modeled home for data from every system — queryable history your BI and AI can trust.","gives":["Warehouse schema and ELT jobs","Data-quality tests in pipeline","Documentation catalog"],"stack":["PostgreSQL / BigQuery / Snowflake","dbt modeling","Airflow orchestration"]},{"id":"dashboards","name":"Dashboards & Reporting","what":"The numbers your teams argue about, computed once and displayed everywhere — live.","gives":["Role-based dashboard suite","KPI definitions agreed and coded","Export and schedule options"],"stack":["Metabase / Power BI","Semantic SQL layer","Alerting rules"]},{"id":"reporting","name":"Regulatory & Operational Reporting","what":"Reports auditors and regulators ask for — generated automatically, archived, traceable.","gives":["Report templates per requirement","Automated generation calendar","Audit-trail of outputs"],"stack":["Templated PDF/Excel engines","Data lineage tracking","Retention policies"]}]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','distribution-erp','en','{"id":"distribution-erp","name":"Distribution ERP","what":"The distribution brain Simal runs for its own JAFZA operation — order-to-cash and procure-to-pay on one real-time core, with AI-assisted replenishment that learns seasonal demand. Multi-warehouse, multi-currency, barcode-driven from receiving dock to delivery.","caps":[["Supply-chain optimization",["AI demand forecasting per SKU","Auto-replenishment proposals","Seasonality and safety-stock learning"]],["Inventory control",["Real-time levels across warehouses","FIFO / AVCO valuation, cycle counts","Barcode receiving, picking, transfers"]],["Order processing",["Order-to-cash with credit checks","Allocations, backorders, drop-ship","Returns and RMA flows"]],["Purchasing",["RFQ → PO → goods receipt → vendor bill","GR/IR matching and approvals","Supplier price lists and scorecards"]],["Analytics",["Margin per customer / SKU / route","Stock-turn and ageing dashboards","Forecast vs. actual accuracy tracking"]]],"flow":[["1 · Map","Process workshops across buying, warehousing and sales; baseline stock accuracy and order-cycle time"],["2 · Configure & migrate","Chart of accounts, warehouses, product data and open orders migrated; UAT on your real transactions"],["3 · Go live & tune","Cutover with rollback plan, then monthly AI-replenishment tuning and AMC support from the Simal desk"]],"deploy":"Built on Odoo 19 Community Edition — $0 per-user licensing, forever. Cloud-hosted or on-premise; your data stays yours.","why":["Runs Simal''s own distribution daily — house practice, not slideware","JAFZA-grade multi-warehouse and multi-currency out of the box","Replenishment improves with every month of your own data"],"faq":[["What size distributor is this for?","From ~5-seat single-warehouse operations to multi-entity groups — module count scales, the core does not change."],["How long is a typical rollout?","8–14 weeks for a single warehouse with clean master data; the desk gives a fixed calendar after the mapping week."]],"related":["retail-erp","unipos","ecommerce-platform"],"services":["custom-dev","devops","data-bi"],"modules":["inventory","crm","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','retail-erp','en','{"id":"retail-erp","name":"Retail ERP","what":"One system for store operations, stock and sales analytics — promotions, pricing and loyalty handled at HQ while every till, shelf and online order stays synchronized in real time.","caps":[["Store operations",["Daily sales, cash-up and shrinkage tracking","Staff roles and permissions per store","Inter-store transfers and stock requests"]],["Stock management",["Size/color matrix products","Replenishment from a central warehouse","Shelf-availability and ageing alerts"]],["Pricing & promotions",["Price lists per channel and segment","Scheduled campaigns and bundles","Markdown and clearance workflows"]],["Loyalty & CRM",["Points, tiers and reward redemption","Customer 360 across every channel","Targeted campaigns from purchase history"]],["Sales analytics",["Like-for-like sales by store","Basket analysis and attach rate","Buyer and category performance"]]],"flow":[["1 · Baseline","Store audit: SKUs, price lists, promotion calendar, integration points with tills and webstore"],["2 · Roll out","HQ first, then stores in waves — each wave trained and live before the next starts"],["3 · Optimize","Monthly category and basket reviews; loyalty campaigns from real purchase data"]],"deploy":"Odoo 19 CE core with POS and loyalty apps — $0 per-user licensing; store hardware spec provided by Simal.","why":["HQ and every store on one real-time ledger — no nightly sync gaps","Promotion and pricing control without store-manager guesswork","Loyalty built in, not a bolt-on subscription"],"faq":[["We already have tills — must we replace them?","No. UniPOS integrates, and for common till brands the team has ready connectors; keep what works."],["Can we run promotions online and in-store together?","Yes — same price lists and campaign engine serve the webstore and the tills."]],"related":["unipos","ecommerce-platform","distribution-erp"],"services":["uiux","custom-dev","data-bi"],"modules":["crm","inventory","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','garments-erp','en','{"id":"garments-erp","name":"Garments ERP","what":"Industry ERP for garment and textile manufacturers — cut-make-trim planning, fabric and trim management with shrinkage control, AQL quality gates and export documentation on one core.","caps":[["Production planning",["Style / PO / batch hierarchy","Cutting, sewing and finishing line loading","Capacity and delivery-date simulation"]],["Material management",["Fabric BOM with shrinkage factors","Auto fabric/trims requirement per plan","Store-to-floor issue and return tracking"]],["Quality control",["AQL sampling at inline and final","Defect analysis by line and operator","Inspection certificates per shipment"]],["Export documentation",["LC, back-to-back LC tracking","Export invoices, packing lists, GSP","Duty-drawback and bond documentation"]],["Costing",["Per-style cost sheet live vs. standard","CM costing per minute / per piece","Margin visibility before you cut fabric"]]],"flow":[["1 · Model the floor","Styles, BOMs, lines and capacity captured; existing costing sheets reconciled"],["2 · Pilot line","One production line runs live alongside spreadsheets until numbers agree"],["3 · Floor-wide","All lines cut over; quality and export modules switched on in sequence"]],"deploy":"Odoo 19 CE manufacturing core with garment extensions — $0 per-user licensing; on-premise or private cloud common in this sector.","why":["Built for the sector the team has implemented for — RMG flows, not generic manufacturing","Fabric and trim control that survives real shrinkage and roll variance","Costing that shows true CM before commitments are cut"],"faq":[["Does it handle piece-rate payroll?","Production and payroll data connect; piece-rate rules are configured per line during implementation."],["Can export docs go out from the system?","Yes — LC tracking through to export invoice and packing list, from the same order record."]],"related":["mps-erp","distribution-erp"],"services":["custom-dev","qa"],"modules":["manufacturing","inventory","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','mps-erp','en','{"id":"mps-erp","name":"Manage Print Service ERP","what":"ERP for managed-print and device-service businesses — click/SLA contracts, meter collection, consumable replenishment and technician dispatch on one system that bills itself.","caps":[["Contract management",["Cost-per-click and SLA contracts","Device-to-contract mapping","Auto-renewal and indexation rules"]],["Meter & usage billing",["Automated meter collection or entry","Volume-tier billing per contract","Overage and minimum-volume handling"]],["Job management",["Service calls and installations","Parts and consumables per device","First-time-fix rate tracking"]],["Equipment scheduling",["Technician calendars and routes","Preventive-maintenance planning","Device uptime dashboards"]],["Cost tracking",["Cost per device and per contract","Parts usage vs. billing reconciliation","Profitability per customer fleet"]]],"flow":[["1 · Fleet inventory","Devices, contracts and meters loaded; billing rules mapped contract by contract"],["2 · Automate billing","First automated billing cycles run in parallel with the old process until matched"],["3 · Dispatch & service","Technician app and PM scheduling switched on; cost dashboards go live"]],"deploy":"Odoo 19 CE with field-service extensions — $0 per-user licensing; meter collectors integrate per device brand.","why":["Contracts, meters and dispatch in one system — no reconciliation spreadsheets","Billing runs itself on collection day","Fleet profitability visible per customer, not per hunch"],"faq":[["Our meters are read manually today — problem?","No: entry screens and CSV import both work; automated collection can follow device by device."],["Does it track toner replenishment?","Yes — usage-triggered consumable proposals flow straight into purchasing."]],"related":["field-service-erp","asset-management"],"services":["mobile","custom-dev"],"modules":["projects","inventory","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','univat','en','{"id":"univat","name":"UniVAT — NBR-Approved VAT Management","what":"One of only five NBR-approved VAT systems in Bangladesh, with direct government-system integration — and Peppol-ready e-invoicing tooling aimed at the UAE''s 1 January 2027 mandate. Every transaction carries correct VAT from the first entry; returns assemble themselves.","caps":[["VAT on every transaction",["Correct calculation at source — sales, purchases, debit/credit notes","HS-code and SROC-driven rates","No month-end scramble to rebuild figures"]],["Government integration",["Direct submission to NBR systems (Bangladesh)","Approved for VAT taxpayers — one of five systems","Return preparation and submission tracking"]],["UAE Peppol readiness",["Structured e-invoice data ahead of the 2027 mandate","Generation and exchange tooling for ASP onboarding","Dubai rollout path run from the Simal desk"]],["Audit & trail",["Every tax event logged and reportable","Revision history with reason codes","Authority-ready drill-down from return to source invoice"]],["Multi-entity",["Per-branch VAT registration handling","Consolidated and per-branch views","Year-end certificates per branch"]]],"flow":[["1 · Registration mapping","BIN/VAT registrations, rates and business rules mapped per entity"],["2 · Parallel run","One full VAT period computed in parallel with the current process — figures must match"],["3 · Submission live","Direct submission switched on; monthly compliance calendar automated"]],"deploy":"Runs as a UniERP module or integrates with an existing ERP — $0 per-user licensing on the Odoo CE core.","why":["Government-approved in Bangladesh — the compliance bar other systems have not cleared","Peppol-ready now, so the 2027 UAE mandate is a switch-on, not a project","VAT correct at entry — not reconstructed at month-end"],"faq":[["We operate in the UAE only — why does NBR approval matter?","It is the hardest compliance bar the team has cleared; the same engineering discipline ships in the Peppol-ready UAE tooling."],["Will it work with our existing ERP?","Yes — UniVAT integrates with non-UniERP ledgers; the desk maps your chart of accounts during discovery."]],"related":["distribution-erp","retail-erp"],"services":["consultancy","devops"],"modules":["univat","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','unipos','en','{"id":"unipos","name":"UniPOS — Multi-Sector Point of Sale","what":"Multi-sector point of sale for retail, fashion and food service — offline-first tills that keep selling when the network drops, syncing inventory and accounts across every location in real time.","caps":[["Multi-sector POS",["Retail, fashion and food-service flows","Touch-optimized till screens per sector","Split bills, holds, refunds, gift cards"]],["Offline-first",["Tills keep trading with no connectivity","Auto-sync and reconcile on reconnect","No lost tickets, no closed-store downtime"]],["Payments",["Card-terminal integration","Cash, card, wallet and mixed tender","End-of-day cash-up per till"]],["Real-time inventory",["Every sale moves stock at HQ instantly","Cross-location stock visibility","Replenishment proposals from sell-through"]],["Multi-location",["Central price lists, local exceptions","Per-store promotions and windows","HQ dashboard across the estate"]]],"flow":[["1 · Fit-out","Till hardware, payment terminals and store network specified per location"],["2 · Store pilot","One store trades live on UniPOS while the old till runs in shadow"],["3 · Estate rollout","Remaining stores in waves; HQ analytics live from day one of each wave"]],"deploy":"Odoo 19 CE POS — $0 per-user licensing; runs on modest till hardware, offline mode included.","why":["Offline-first — connectivity outages stop costing sales","One inventory truth across tills, stores and the webstore","Sector screens mean less training, faster queues"],"faq":[["What happens when the internet drops mid-sale?","The till keeps serving and queues every transaction; reconciliation is automatic on reconnect."],["Can it share stock with our webstore?","Yes — that is the design default: tills and e-commerce read and write the same inventory."]],"related":["retail-erp","ecommerce-platform","queue-management"],"services":["uiux","mobile"],"modules":["inventory","crm","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','education-erp','en','{"id":"education-erp","name":"Education Management ERP","what":"Complete management system for schools, colleges and universities — student records, academics, fees and parent communication on one platform that replaces the admin corridor.","caps":[["Student information",["Admission to alumni records","Documents, attendance, discipline","Guardian and sibling linkage"]],["Academic management",["Courses, sections, timetables","Exams, grading schemes, report cards","Teacher workload and substitutions"]],["Fee management",["Fee structures, scholarships, instalments","Online payment and receipts","Defaulter tracking and reminders"]],["Transport & hostel",["Routes, stops, vehicle tracking","Hostel rooms and allocations","Mess and library modules"]],["Portals",["Student and parent self-service","Teacher gradebook entry","Noticeboard and announcements"]]],"flow":[["1 · Academic mapping","Programs, curricula, fee structures and grading rules configured per campus"],["2 · Admission cycle","Go live for a full admission cycle — applications, lists, enrolment, fees"],["3 · Whole institution","Academics, transport and portals roll out term by term"]],"deploy":"Odoo 19 CE education core — $0 per-user licensing; campus-hosted or cloud per policy.","why":["One record per student across admissions, academics and money","Parents self-serve instead of queueing at the office","Fee leakage visible and recoverable"],"faq":[["We have three campuses with different fee rules — supported?","Yes — fee structures are per-campus with shared student records and consolidated reporting."],["Can teachers use it without training overhead?","Gradebook and attendance are teacher-first screens; adoption workshops are part of rollout."]],"related":["i-portal","queue-management"],"services":["custom-dev","mobile"],"modules":["finance","hr"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','field-service-erp','en','{"id":"field-service-erp","name":"Field Service Automation ERP","what":"Field-service automation — work orders, dispatch, technician mobile app, parts van-stock and SLA-backed billing in one loop from customer call to invoice.","caps":[["Work-order management",["Call to work order to invoice","Priority, skills and site mapping","Customer service history at hand"]],["Scheduling & dispatch",["Calendar and map-based assignment","Travel-time-aware scheduling","Reassignment and escalation rules"]],["Technician app",["Jobs, checklists and photos on mobile","Parts used and time logged on site","Digital sign-off and instant report"]],["Parts & inventory",["Van stock, main store, returns","Parts reservations per work order","Reorder proposals from usage"]],["SLA & billing",["Response and resolution SLA tracking","Contract vs. ad-hoc billing rules","First-time-fix and revisit analytics"]]],"flow":[["1 · Contract & service setup","SLAs, service items, skills and territories defined; billing rules agreed"],["2 · Dispatch pilot","One region runs the mobile app with shadow invoicing until matched"],["3 · Full operation","All regions live; SLA and parts dashboards reviewed monthly"]],"deploy":"Odoo 19 CE field-service core — $0 per-user licensing; Android/iOS technician app included.","why":["The whole loop — call, fix, parts, bill — in one system","SLA performance provable to customers","Paperless technicians with sign-off on site"],"faq":[["Do technicians need special devices?","No — the app runs on standard Android/iOS phones; rugged hardware optional per fleet policy."],["Can it bill against maintenance contracts?","Yes — contract-covered visits and billable work are separated automatically at invoicing."]],"related":["mps-erp","asset-management"],"services":["mobile","custom-dev"],"modules":["projects","inventory","hr"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','hotel-erp','en','{"id":"hotel-erp","name":"Hotel Management ERP","what":"Hotel operations from reservation to checkout — front desk, housekeeping, F&B and billing on one system, with channel-manager integration so OTA and direct bookings share the same room inventory.","caps":[["Reservation management",["Bookings, groups, allotments","Channel-manager integration for OTAs","Room-rack and availability calendar"]],["Front desk",["Check-in / check-out, room moves","Folio and guest history","Walk-in and corporate accounts"]],["Housekeeping",["Room-status boards","Cleaning schedules and inspection","Maintenance requests from rooms"]],["F&B & POS",["Restaurant and room-service tills on UniPOS","Recipe costing and stock","Mini-bar and banquet billing"]],["Billing integration",["City ledger and travel-agent accounts","Package rates and extra charges on one folio","Night audit and day-close reports"]]],"flow":[["1 · Property setup","Room types, rates, seasons, outlets and chart of accounts configured"],["2 · Parallel bookings","New reservations run live while the legacy PMS continues for in-house guests"],["3 · Cutover & train","Night audit, housekeeping and F&B live; front-desk certification per shift"]],"deploy":"Odoo 19 CE hospitality core with UniPOS for outlets — $0 per-user licensing.","why":["Rooms, outlets and ledgers genuinely on one system — not interfaced islands","OTA and direct bookings against the same inventory","Night audit that closes itself"],"faq":[["Does it connect to Booking.com / Expedia?","Through standard channel-manager integrations — the desk confirms your channel list in discovery."],["Can we start with just the front desk?","Yes — modules switch on in stages; outlets and housekeeping can follow a season later."]],"related":["unipos","queue-management"],"services":["uiux","custom-dev"],"modules":["crm","finance","inventory"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','hospital-erp','en','{"id":"hospital-erp","name":"Hospital Management ERP","what":"Hospital and medical-center management — patient records, appointments, pharmacy, lab and insurance-ready billing on one system, engineered to ISO 27001 discipline for patient data.","caps":[["Patient records",["EMR with history and documents","Consultant notes and prescriptions","Privacy-controlled access per role"]],["Appointment scheduling",["Doctor calendars and slots","Multi-channel booking and reminders","No-show and follow-up tracking"]],["Pharmacy",["Stock by batch and expiry","Prescription-to-dispense flow","Reorder and supplier management"]],["Diagnostics",["Lab orders and result entry","Report templates per test","Imaging references and links"]],["Billing & insurance",["Service tariffs and packages","Insurance claim preparation","Corporate patient accounts"]]],"flow":[["1 · Clinical mapping","Departments, tariffs, doctors and privacy roles configured with the medical team"],["2 · Outpatient pilot","OPD registration → consultation → pharmacy runs live for one department"],["3 · Full hospital","IPD, lab, insurance billing and analytics activated in sequence"]],"deploy":"Odoo 19 CE healthcare core — $0 per-user licensing; on-premise or private-cloud hosting per data-residency policy.","why":["Patient data handled under ISO 27001-certified discipline","One patient record from registration to pharmacy","Insurance claims prepared from the same billing engine"],"faq":[["How is patient privacy protected?","Role-based access, full audit trail, and hosting options that keep data in-policy — reviewed under the team''s ISO 27001 regime."],["Can lab equipment connect directly?","Common analyzers integrate via standard interfaces; the desk inventories your equipment during discovery."]],"related":["queue-management","i-portal"],"services":["cybersecurity","qa"],"modules":["hr","finance","inventory"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','ecommerce-platform','en','{"id":"ecommerce-platform","name":"E-commerce Platform","what":"Launch-and-scale e-commerce — storefront, catalog, payments, shipping and order management wired into the same inventory as your physical channels, with AI-assisted merchandising.","caps":[["Online storefront",["Catalog with variants and media","Responsive storefront themes","Multi-language, multi-currency"]],["Payment gateway",["Local and international gateways","Wallets and cash-on-delivery","Fraud-screening hooks"]],["Shipping integration",["Courier and rate connectors","Label generation and tracking","Zone-based delivery rules"]],["Order management",["One queue for web, marketplaces, stores","Pick-pack-ship workflows","Returns portal and refunds"]],["AI merchandising",["Recommendations from behaviour","Search relevance tuning","Abandoned-basket triggers"]]],"flow":[["1 · Store build","Catalog, brand theme, payment and shipping connectors stood up"],["2 · Soft launch","Friendly customers trade; fulfilment and finance reconciliation proven"],["3 · Scale","Marketing automation and marketplace channels switched on with analytics"]],"deploy":"Odoo 19 CE commerce core — $0 per-user licensing; hosting scales from launch traffic to seasonal peaks.","why":["Web, tills and warehouse read one inventory — overselling ends","AI features are included, not a plugin subscription","Fulfilment and finance reconcile daily, automatically"],"faq":[["Can it handle our existing product catalog?","Yes — catalogs import with variants and images; enrichment happens in the CMS-side tools."],["Which payment gateways are supported?","Major regional and international gateways plus COD; your acquirer list is confirmed at kickoff."]],"related":["retail-erp","unipos","distribution-erp"],"services":["custom-dev","aiml","uiux"],"modules":["inventory","crm"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','weather-systems','en','{"id":"weather-systems","name":"Weather Forecast Production Systems","what":"Professional weather-forecast production — data ingestion from stations and satellites, numerical model runs, forecaster workstations and automated alert dissemination for meteorological operations.","caps":[["Data ingestion",["Station, radar and satellite feeds","Quality control and gap filling","Gridded and observational archives"]],["Forecast production",["Model-run pipelines (WRF-family)","Nowcasting and medium-range products","Forecaster workstation dashboards"]],["Alert generation",["Threshold-based warning rules","Sector-specific alert products","Multi-channel dissemination (web, API, SMS)"]],["Publication",["Public website and API delivery","Aviation / marine product formats","Archive and verification statistics"]],["Verification",["Forecast vs. observed scoring","Model-skill comparison","Product-improvement reporting"]]],"flow":[["1 · Feed integration","Data sources, formats and schedules connected; archives backfilled"],["2 · Production trial","Model runs and products generated in parallel with existing operations"],["3 · Operational handover","Forecasters certified on workstations; dissemination channels live"]],"deploy":"Bespoke production stack on cloud or on-premise HPC — scoped per national-met requirement.","why":["A niche the team has genuinely delivered in — not a generic BI repackaging","Every forecast product verified against observations","Dissemination built-in: the alert is the product"],"faq":[["Which model does it run?","WRF-family numerical cores are house-standard; the configuration is tuned to your domain and compute."],["Can it just distribute our existing forecasts?","Yes — dissemination and verification can run against products you already produce."]],"related":["i-portal"],"services":["data-bi","cloud","custom-dev"],"modules":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','cattle-management','en','{"id":"cattle-management","name":"Cattle Management Systems","what":"Livestock management for agricultural operations — herd registry, health and vaccination programs, breeding cycles and feed planning, with analytics that spot problems weeks before they spread.","caps":[["Herd registry",["Individual animal records and lineage","Ear-tag / RFID identification","Group and paddock assignment"]],["Health monitoring",["Vaccination and treatment calendar","Symptom and incident logging","Withdrawal-period tracking"]],["Breeding management",["Heat detection and insemination logs","Gestation and calving forecasts","Genetic lineage reporting"]],["Feed management",["Ration plans per group","Feed stock and cost tracking","Weight-gain vs. feed-efficiency analytics"]],["Farm analytics",["Herd performance dashboards","Mortality and morbidity trends","Cost per head and per litre of milk"]]],"flow":[["1 · Herd census","Animals tagged and registered; groups, paddocks and rations mapped"],["2 · Health programs","Vaccination and treatment calendars live; mobile logging for field staff"],["3 · Analytics on","Breeding and feed dashboards tuned per season with the farm team"]],"deploy":"Odoo 19 CE core with livestock extensions — $0 per-user licensing; mobile logging on standard phones.","why":["One registry from birth to sale or loss","Health calendar prevents the outbreak that costs a season","Feed-efficiency numbers, not guesswork"],"faq":[["Does it need special tags or hardware?","It works with your existing ear tags; RFID readers are optional and integrate when you add them."],["Can field staff use it without signal?","Mobile logging caches offline and syncs — the same pattern as the UniPOS tills."]],"related":["weather-systems","asset-management"],"services":["mobile","aiml"],"modules":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','queue-management','en','{"id":"queue-management","name":"Queue Management Systems","what":"Intelligent customer-flow management — virtual and ticketed queuing that cuts perceived wait times, with kiosk join, real-time displays and staff dashboards for branches, clinics and service centers.","caps":[["Virtual queuing",["Join by app, SMS or web — no physical line","Estimated wait and ready notifications","Appointment + walk-in blending"]],["Ticketed queuing",["Kiosk and counter ticket issue","Segment routing (service type, priority)","Counter call and recall flows"]],["Real-time displays",["Waiting-count and now-serving screens","Counter and service-status boards","Audio and visual call alerts"]],["Staff dashboards",["Serve, transfer, pause per counter","Service-time tracking","Load balancing across counters"]],["Analytics",["Wait and service-time distributions","Peak-hour staffing evidence","Customer satisfaction links"]]],"flow":[["1 · Flow mapping","Services, counters and routing rules captured from your floor plan"],["2 · Counter pilot","One service line goes live with kiosk and display; staff trained per counter"],["3 · Full venue","All counters and virtual queuing on; analytics reviewed weekly"]],"deploy":"Lightweight deployment on standard hardware — kiosk, screens, counter terminals; $0 per-user licensing on the Odoo CE core.","why":["Perceived wait collapses even when physical throughput is unchanged","Staffing decisions get queue-length evidence","Blends appointments with walk-ins fairly"],"faq":[["Do customers need an app?","No — web and SMS joining cover most deployments; the app is optional."],["Can it prioritize elderly or disabled visitors?","Yes — priority classes are a standard routing rule, configurable per service."]],"related":["hospital-erp","unipos"],"services":["uiux","mobile"],"modules":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','collection-recovery','en','{"id":"collection-recovery","name":"Collection & Recovery Management","what":"Debt-collection and recovery management — strategy-driven worklists, automated multi-channel reminders, field-agent tooling and recovery analytics that raise promise-to-pay rates.","caps":[["Debtor ledger",["Single view of every obligation","Segmentation by age, amount, risk","Promise-to-pay tracking"]],["Strategy worklists",["Champion/challenger collection strategies","Agent queues weighted by propensity models","Escalation ladders per segment"]],["Automated reminders",["SMS, email, letter cadences","Payment-link inclusion","Response capture and rescheduling"]],["Field operations",["Agent routes and visit logging","Mobile evidence and receipts","Safety check-ins"]],["Recovery analytics",["Cure-rate per strategy and agent","Roll-rate and vintage analysis","Cost-to-collect measurement"]]],"flow":[["1 · Portfolio load","Books, segments and existing strategies imported; cure baseline measured"],["2 · Cadence live","Automated reminder cadences replace manual calling lists"],["3 · Optimize","Propensity-scored worklists and field routes tuned monthly against cure rates"]],"deploy":"Odoo 19 CE core with collection extensions — $0 per-user licensing; integrates with your source ledgers.","why":["Strategy testing, not folklore — champion/challenger by default","Agents work scored lists, not phone books","Every contact and promise is measurable"],"faq":[["Does it replace our core banking ledger?","No — it reads obligations from your ledger and writes results back; the ledger stays the system of record."],["How do propensity scores get built?","From your own historical cure data during implementation; models retrain on results monthly."]],"related":["loan-management","merchant-banking"],"services":["aiml","custom-dev"],"modules":["finance","crm"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','loan-management','en','{"id":"loan-management","name":"Loan Management Solution","what":"End-to-end lending — application and KYC, scoring and approval, disbursement, repayment schedules and NPL monitoring, from microfinance to structured SME portfolios.","caps":[["Application & KYC",["Digital applications, document capture","KYC/AML screening hooks","Officer and branch pipelines"]],["Credit assessment",["Rule + scorecard decisioning","Affordability and exposure checks","Approval ladders and exceptions"]],["Disbursement",["Account setup and payout instructions","Tranche and milestone releases","Fee and insurance handling"]],["Repayment management",["Amortization and schedule variants","Collections alignment and arrears flags","Settlement and early-close quotes"]],["Portfolio monitoring",["NPL and PAR dashboards","Vintage and concentration analysis","Provisioning support reports"]]],"flow":[["1 · Product setup","Loan products, scorecards and approval rules configured with credit officers"],["2 · Pilot book","One branch or product originates live in parallel with the current process"],["3 → Full rollout","All branches live; portfolio dashboards and NPL alerts operational"]],"deploy":"Odoo 19 CE core with lending extensions — $0 per-user licensing; ledger integration per your core system.","why":["Origination to NPL on one record — no reconciliation between systems","Scorecards your credit team can tune themselves","Provisioning numbers straight from live arrears"],"faq":[["Does it do mobile-money disbursement?","Payout instructions integrate with common wallets and bank rails; your rails are confirmed in discovery."],["Can scoring use alternative data?","Yes — scorecard inputs are configurable; the data-bi team builds and validates them with your historians."]],"related":["collection-recovery","custodian-banking"],"services":["aiml","cybersecurity"],"modules":["finance","crm"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','custodian-banking','en','{"id":"custodian-banking","name":"Custodian Banking Solution","what":"Custodian banking — safekeeping, settlement, corporate-action processing and client reporting for institutions that hold assets on behalf of clients, with regulatory reporting built in.","caps":[["Safekeeping",["Segregated client asset registers","Instrument master data","Pledge and lien tracking"]],["Settlement",["Trade capture and matching","Settlement instruction lifecycle","Fails management and buy-ins"]],["Corporate actions",["Event capture and entitlement calculation","Client elections and instructions","Income collection and distribution"]],["Client reporting",["Portfolio statements per mandate","Transaction and income reports","Portal delivery options"]],["Regulatory reporting",["Position and exposure reports","Audit trail per instruction","Reconciliation to depositories"]]],"flow":[["1 · Instrument & mandate setup","Instrument master, custody mandates and depository connections mapped"],["2 · Settlement parallel","Live instructions processed in shadow until reconciliations match depository records"],["3 · Full custody","Corporate actions and client reporting live; regulatory calendar automated"]],"deploy":"Odoo 19 CE core with custody extensions — $0 per-user licensing; private-cloud deployment standard in this sector.","why":["Every instruction auditable end to end — the regulator''s first question answered","Corporate actions processed, not survived","Client statements generated, not assembled"],"faq":[["Which depositories does it connect to?","Connections are built per market during implementation — the team''s integration practice handles the interface work."],["Can it run alongside our core banking platform?","Yes — custody operates as a satellite with reconciliation back to the core ledger."]],"related":["merchant-banking","loan-management","asset-management"],"services":["cybersecurity","qa"],"modules":["finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','i-portal','en','{"id":"i-portal","name":"I-Portal Solution","what":"Centralized enterprise portal — single sign-on, user management and content integration that gives staff, customers and partners one front door to applications and information.","caps":[["Centralized access",["Single sign-on across applications","Role-based navigation and menus","Session and device policies"]],["User management",["Directory sync (AD/LDAP)","Joiner-mover-leaver workflows","Delegated administration per unit"]],["Content integration",["Portlets from line-of-business systems","Document libraries and news","Personalized dashboards"]],["Workflow & forms",["Approval workflows and forms builder","Service-request catalog","SLA tracking per request"]],["Experience layer",["Responsive design, Arabic-ready RTL","Theme aligned to your brand","Usage analytics per audience"]]],"flow":[["1 · Audience mapping","Personas, application inventory and access rules captured"],["2 · SSO foundation","Directory integration and role model live; first applications federated"],["3 → Portal build-out","Content, workflows and dashboards added per audience wave"]],"deploy":"Modern web stack integrated with your directory — $0 per-user licensing on the Odoo CE core where workflows apply.","why":["One front door — password sprawl and link farms retired","Access follows HR reality: joiners get in, leavers are out same-day","Content and workflows from systems you already run"],"faq":[["Will it work with Active Directory?","Yes — AD/LDAP sync is standard; group mapping drives portal roles."],["Can it be customer-facing too?","Yes — partner and customer audiences with separate themes and entitlements are a standard pattern."]],"related":["education-erp","hospital-erp"],"services":["custom-dev","cybersecurity"],"modules":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','asset-management','en','{"id":"asset-management","name":"Asset Management Solution","what":"Asset lifecycle management — registry, maintenance scheduling, depreciation and audit-proof tracking from acquisition to disposal, with QR-based physical verification.","caps":[["Asset registry",["Asset hierarchy and locations","Warranty and insurance records","Custodian assignment"]],["Maintenance scheduling",["Preventive calendars per class","Work orders to internal or vendor teams","Downtime history per asset"]],["Depreciation",["Straight-line and declining methods","Books per reporting standard","Automatic ledger posting"]],["Physical audit",["QR/scan verification rounds","Found / missing / moved reconciliation","Tag printing and re-tagging"]],["Lifecycle analytics",["Cost of ownership per asset","Repair-vs-replace signals","Disposal and gain/loss processing"]]],"flow":[["1 · Census & tagging","Assets tagged and registered; custodians and locations verified"],["2 → Books & maintenance","Depreciation rules live in the ledger; preventive calendars started"],["3 → Audit cycles","QR verification rounds run; disposal workflow with gain/loss posting"]],"deploy":"Odoo 19 CE asset core — $0 per-user licensing; QR tags printable on standard label printers.","why":["Audit rounds measured in hours, not quarters","Depreciation posts itself — no spreadsheet reconciliation","Repair-vs-replace decisions get cost-of-ownership evidence"],"faq":[["We have an existing asset list — can it be imported?","Yes — registers import from spreadsheets or your current system; tagging follows the census."],["Does it link maintenance to finance?","Yes — work orders carry costs to the asset record, and depreciation flows straight to the ledger."]],"related":["field-service-erp","mps-erp"],"services":["mobile","data-bi"],"modules":["inventory","finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_solution','merchant-banking','en','{"id":"merchant-banking","name":"Merchant Banking Solution","what":"Merchant-banking operations — issue management, underwriting, portfolio services and client-money handling with regulatory reporting on one compliant core.","caps":[["Issue management",["IPO and rights-issue processing","Application collection and allotment","Refund and settlement handling"]],["Underwriting",["Syndicate formation and stakes","Exposure and commitment tracking","Fee and commission accounting"]],["Portfolio services",["Client portfolio registers","Corporate-action pass-through","Advisory mandate tracking"]],["Client money",["Segregated client accounts","Movement approvals and audit trail","Reconciliation to custodian records"]],["Regulatory compliance",["Capital-exposure reports","Transaction reporting calendars","Audit-ready evidence packs"]]],"flow":[["1 · Mandate & product setup","Issue types, syndicate rules and client-money controls configured"],["2 → Issue pilot","One live issue processed end to end alongside existing controls"],["3 → Continuous operation","Portfolio services and regulatory calendars automated"]],"deploy":"Odoo 19 CE core with merchant-banking extensions — $0 per-user licensing; private-cloud deployment standard.","why":["Issue processing without spreadsheet risk at the money moments","Client money segregation with an audit trail by design","Regulatory reports assembled, not reconstructed"],"faq":[["Can it handle syndicated issues across multiple underwriters?","Yes — syndicate stakes, fee splits and settlement are first-class records."],["How is client money protected?","Segregated accounts with approval-gated movements and full audit logging — reviewed under ISO 27001 discipline."]],"related":["custodian-banking","loan-management"],"services":["cybersecurity","qa"],"modules":["finance"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','healthcare','en','{"id":"healthcare","name":"Healthcare & Medical","what":"Clinical operations under one record — hospitals, clinics and diagnostic groups running patient journeys, pharmacy stock and insurance-ready billing without paper corridors. Built and supported under ISO 27001 discipline, because patient data tolerates no shortcuts.","pains":["Paper records split one patient across departments — no single history at the point of care","Pharmacy expiry and stock leaks drain margins invisibly","Insurance claim preparation is manual and disputed line by line"],"plays":[["1 · Clinical mapping","Departments, tariffs, doctors and privacy roles mapped with your medical team — not at them"],["2 · OPD pilot","One outpatient department runs registration → consultation → pharmacy live, in shadow alongside existing practice"],["3 · Full hospital","IPD, lab, insurance billing and analytics activate in sequence, with per-shift front-desk certification"]],"faq":[["Can you integrate with our lab analyzers?","Common analyzers connect through standard interfaces — the desk inventories your equipment during discovery, before any commitment."],["How is patient privacy handled?","Role-based access, a complete audit trail, and hosting that meets your data-residency policy — governed under the team''s ISO 27001 regime."]],"services":["cybersecurity","qa","custom-dev"],"related":["education","government"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','banking','en','{"id":"banking","name":"Finance & Banking","what":"Mission-critical financial systems handling billions in transactions — lending, custody, merchant banking and collections on cores engineered for the security, reliability and regulatory compliance the sector demands.","pains":["Reconciliation between lending, custody and the core banking platform eats whole departments","Regulatory reports are reconstructed by hand at period end","Client money and audit trails must be provably segregated — and provably so to a regulator"],"plays":[["1 · Risk & compliance mapping","Mandates, client-money controls and regulatory calendars mapped before a single screen is built"],["2 · Parallel processing","Live instructions run in shadow against existing controls until reconciliations match to the record"],["3 · Regulated live","Reporting calendars automated; every instruction auditable end to end"]],"faq":[["Does this replace our core banking platform?","No — the solutions run as satellites with reconciliation back to your core; the core ledger stays the system of record."],["How do you prove compliance to our regulator?","Segregation, audit trails and exposure reports are built-in outputs of the system — not period-end scramble deliverables."]],"services":["cybersecurity","qa","data-bi"],"related":["government","realestate"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','retail','en','{"id":"retail","name":"E-commerce & Retail","what":"Complete commerce ecosystems — tills, webstore, warehouse and loyalty on one inventory truth, handling peak seasons without overselling and promotions without margin surprises.","pains":["Channel stock drifts — the webstore sells what the shelf already promised","Promotion and pricing control lives in store managers'' heads","Loyalty is a bolt-on subscription instead of built-in buying behavior"],"plays":[["1 · Channel audit","Tills, webstore and warehouse integration points audited against real SKU data"],["2 · Store pilot","One location trades live on UniPOS while the old till runs in shadow"],["3 · Unified commerce","HQ analytics, loyalty and replenishment live from day one of each rollout wave"]],"faq":[["Can we keep our existing tills?","For common till brands, ready connectors exist — keep what works, replace what hurts."],["What about peak-season load?","Hosting scales from launch traffic to seasonal peaks; the platform is sized against your trading calendar, not an average."]],"services":["uiux","aiml","custom-dev"],"related":["logistics","manufacturing"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','manufacturing','en','{"id":"manufacturing","name":"Manufacturing & Industry","what":"Production floors that plan from real demand — BOM, MRP, work orders and quality gates for RMG, pharma, food and discrete plants, with true costing visible before commitments are cut.","pains":["Planning runs on spreadsheets disconnected from the shop floor","Material and shrinkage variance erodes margins invisibly","Quality is inspected in at the end instead of built in at every stage"],"plays":[["1 · Floor modeling","Styles, BOMs, lines and capacity captured; existing costing sheets reconciled line by line"],["2 · Pilot line","One production line runs live alongside spreadsheets until the numbers agree"],["3 · Plant-wide","All lines cut over; quality gates and export documentation switch on in sequence"]],"faq":[["We are not garments — does this fit?","The manufacturing core (BOM / MRP / work orders) is sector-neutral; sector flows are configured on top — implementations span RMG, print services and discrete plants."],["Can it calculate true CM cost?","Yes — cost sheets run live vs. standard from actual floor data, per style or per batch."]],"services":["custom-dev","qa","data-bi"],"related":["logistics","agriculture"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','education','en','{"id":"education","name":"Education & E-learning","what":"Institutions run on one student record — admissions, academics, fees and parent communication on a platform that empties the admin corridor and keeps guardians out of queues.","pains":["Student data lives in three offices and none of them agree","Fee leakage and defaulter tracking stay invisible until year end","Parents queue for answers the system should have published"],"plays":[["1 · Academic mapping","Programs, curricula, fee structures and grading rules configured per campus"],["2 · Admission cycle","Go live for a full admission cycle — applications through enrolment and fees"],["3 · Whole institution","Academics, transport, hostel and portals roll out term by term"]],"faq":[["Multiple campuses with different fee rules — problem?","No — fee structures are per-campus over shared student records, with consolidated reporting."],["What about teacher adoption?","Gradebook and attendance are teacher-first screens; adoption workshops are part of every rollout."]],"services":["custom-dev","mobile","uiux"],"related":["government","healthcare"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','government','en','{"id":"government","name":"Government & Public Sector","what":"Public-sector service delivery on secure, compliant platforms — citizen queues, VAT automation and portals that make transparency an output of the system rather than a reporting exercise.","pains":["Citizen wait times outlast the service itself","Tax and VAT compliance is reconstructed manually each period","Systems bought per department cannot talk to each other"],"plays":[["1 · Service inventory","Citizen services, volumes and SLAs catalogued with the department"],["2 · Queue & portal pilot","One service center goes live with queue management and the citizen portal"],["3 · Integrated services","Departments federate through I-Portal with shared identity and access rules"]],"faq":[["Can it integrate across departments?","Yes — I-Portal federates line-of-business applications behind single sign-on with role-based access."],["Is Arabic / RTL supported?","The platform is bilingual with RTL parity — Arabic-ready screens are standard, not an afterthought."]],"services":["cybersecurity","custom-dev","consultancy"],"related":["education","banking"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','logistics','en','{"id":"logistics","name":"Logistics & Supply Chain","what":"Warehouse-to-delivery visibility — multi-warehouse stock, transportation planning and supply-chain analytics that locate every unit and expose the routes, docks and handoffs that leak time.","pains":["Stock is where the spreadsheet says it is — not where it actually is","Transport planning is tribal knowledge in a dispatcher''s head","Customers ask \"where is it\" and nobody can answer quickly"],"plays":[["1 · Network mapping","Warehouses, routes, carriers and handoffs mapped against real volumes"],["2 · Warehouse live","Barcode receiving, picking and cycle counts live in one facility first"],["3 · Network visibility","Transport planning and tracking extend across the whole network"]],"faq":[["Do we need special scanning hardware?","Standard Android scanners and phones work; rugged hardware is optional per environment."],["Can it connect to carrier systems?","Common courier and rate connectors exist; your carrier list is confirmed at kickoff."]],"services":["custom-dev","data-bi","cloud"],"related":["retail","manufacturing"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','realestate','en','{"id":"realestate","name":"Real Estate & PropTech","what":"Property operations platforms — tenant experience, maintenance and portfolio financials that treat a building as a living asset instead of a folder of spreadsheets.","pains":["Tenant requests vanish into WhatsApp threads","Maintenance is reactive and asset history simply does not exist","Owner reporting is assembled manually every quarter"],"plays":[["1 · Portfolio setup","Properties, units, tenants and service-charge structures configured"],["2 · Tenant portal live","Requests, bookings and notices flow through the portal with SLA tracking"],["3 · Financial close","Service charges, maintenance costs and owner reporting automated"]],"faq":[["Does it handle service charges?","Yes — charge structures, billing and reconciliation per property and unit are core records."],["Can tenants track their own requests?","Yes — the portal shows status and the SLA clock without a single call to the office."]],"services":["custom-dev","mobile","uiux"],"related":["logistics","government"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('software_industry','agriculture','en','{"id":"agriculture","name":"Agriculture & AgriTech","what":"Livestock and agri operations managed like a business — herd registry, health programs, feed efficiency and weather-informed planning (content §15), from calf to cull and season to season.","pains":["Herd knowledge walks out the gate with the foreman","Health events are remembered, not recorded — outbreaks spread in the gaps","Feed cost per head is a guess, not a number"],"plays":[["1 · Herd census","Animals tagged and registered; groups, paddocks and rations mapped"],["2 · Health programs","Vaccination and treatment calendars live, with mobile logging for field staff"],["3 · Season analytics","Breeding, feed and weight-gain dashboards tuned per season with the farm team"]],"faq":[["Does it work without farm connectivity?","Mobile logging caches offline and syncs when signal returns — the same pattern the tills use."],["Can it use weather data?","Yes — the weather-systems practice feeds alerts and planning data where the operation wants it."]],"services":["mobile","aiml","data-bi"],"related":["manufacturing"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','infra','en','{"id":"infra","icon":"🖧","t":"IT Infrastructure Solutions","d":"Turnkey design, supply and deployment of server, storage and workplace infrastructure.","what":"One accountable partner for the whole estate — workplace devices, servers, storage and the network that binds them, specified from our 78-SKU authorized portfolio, staged at JAFZA and deployed to site with documentation your next auditor can follow.","scope":[["Workplace infrastructure",["Laptops, desktops and monitors from stock","Standard golden images and BIOS policies","Docking, UPS and accessory kits"]],["Server & storage",["Sizing from workload, not vendor rebate","Virtualization and shared storage design","Warranty and DOA handling through our desk"]],["Deployment",["Staging and imaging at JAFZA before site","Data and profile migration","Site documentation and asset register handover"]],["Lifecycle",["Refresh planning with real failure data","Trade-in and disposal handling","Standardization roadmaps per department"]]],"process":[["1 · Assess","Inventory and workload baseline; gaps and end-of-life flagged against refresh budget"],["2 · Stage","Devices imaged, tested and asset-tagged at JAFZA; delivery scheduled per site"],["3 · Deploy & hand over","Rollout in waves with per-site sign-off and the asset register documented"]],"faq":[["Can you supply and deploy kit we already chose?","Yes — supply-only and supply+deploy are both standard; our value is the JAFZA staging and single desk for warranty."],["We buy from several brands — problem?","No. The portfolio spans 21 authorized brands; standardization guidance is advice, never a condition."]],"related":["managed","support"],"cats":["laptops","monitors"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','amc','en','{"id":"amc","icon":"📅","t":"AMC (Annual Maintenance Contract)","d":"Scheduled preventive maintenance with guaranteed response SLAs across UAE sites.","what":"Comprehensive maintenance covering hardware, software and network infrastructure with defined SLA tiers, proactive monitoring and 24/7 support options — the response-time promise is written into the contract, not the brochure.","scope":[["Preventive maintenance",["Scheduled visits: quarterly, monthly or unlimited by tier","Firmware, patch and health-check cycles","Asset condition reports per visit"]],["Response & resolution",["Contracted response: 1h / 4h / next business day","Resolution targets per tier (see SLA table)","Escalation path named in the contract"]],["Spares & logistics",["JAFZA-fulfilled spare pool for covered assets","Advance replacement where warranty allows","Consumables logistics for printers and devices"]],["Reporting",["SLA performance reports per period","Incident and root-cause summaries","Quarterly review with recommendations"]]],"process":[["1 · Asset audit","Covered assets inventoried; age, criticality and warranty mapped"],["2 · Tier selection","Response/resolution tier chosen per asset class — critical systems on 1h, edge devices on NBD"],["3 · Contract & SLA reporting","Annual contract with named escalation; SLA performance reported every period"]],"faq":[["Is AMC only for hardware we bought from Simal?","No — the service desk is vendor-agnostic; third-party assets enter the contract after an intake audit."],["What is excluded from an AMC?","Physical damage, consumables beyond contracted volumes and out-of-scope software changes — exclusions are listed in the contract, not discovered at invoice time."]],"related":["support","managed"],"cats":[],"tiers":true}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','managed','en','{"id":"managed","icon":"📦","t":"Managed Services","d":"Fully outsourced IT operations, monitoring and lifecycle management for SMEs and enterprises.","what":"Your IT department, contracted — monitoring, patching, user support and lifecycle planning run to an SLA, with a named service manager and monthly reporting that ties every dirham spent to tickets closed and risks retired.","scope":[["Monitoring & alerting",["24/7 infrastructure and endpoint monitoring","Alert triage before users notice","Monthly availability reporting"]],["Patch & configuration",["OS and third-party patch cycles","Standard hardened configurations","Drift detection and remediation"]],["User support",["Helpdesk with contracted response tiers","Onboarding / offboarding automation","Asset tracking per user"]],["Planning",["Named service manager","Quarterly roadmap and budget reviews","Lifecycle and refresh planning"]]],"process":[["1 · Onboard","Environment discovery, monitoring agents and access model set up in weeks, not quarters"],["2 · Stabilize","Backlog burned down; patch levels and alert noise brought to baseline"],["3 · Run & improve","SLA reporting monthly; roadmap reviews quarterly with your service manager"]],"faq":[["We have internal IT — does managed replace them?","No — most deployments co-manage: we take monitoring, patching and after-hours, your team keeps strategy and intimate apps."],["How is pricing structured?","Per-user or per-asset bands from the discovery inventory — quoted before onboarding, no per-ticket surprises."]],"related":["amc","infra"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','network-security','en','{"id":"network-security","icon":"🔐","t":"Network and IT Security Solutions","d":"Secure switching, routing and access with policy-based segmentation.","what":"Networks designed so the blast radius of any compromise is one VLAN, not the company — segmented switching, controlled wireless and access policy designed, supplied and documented.","scope":[["Segmentation",["VLAN design per department and device class","Guest and IoT isolation by default","Inter-zone policy documented and reviewable"]],["Switching & routing",["Access and distribution switching from the authorized portfolio","Redundant uplink and gateway design","Configuration standards and backups"]],["Secure access",["802.1X / NAC readiness","Wireless with certificate-based access","Visitor networks with time-boxed access"]],["Physical security",["Surveillance and access-control integration (Hikvision line)","Camera-to-VLAN isolation","Retention aligned to policy"]]],"process":[["1 · Discover","Current topology, traffic flows and compliance needs mapped"],["2 · Design","Segmentation and access policy designed and reviewed with your team"],["3 · Implement","Staged changes with rollback plans; as-built documentation handed over"]],"faq":[["Will segmentation break our legacy applications?","Inter-zone rules are piloted in monitor mode first; nothing is enforced until flows are proven."],["Do you also maintain the network after deployment?","Yes — under an AMC or managed contract, with config backups and change control."]],"related":["firewall","cloud-security"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','firewall','en','{"id":"firewall","icon":"🧱","t":"Firewall Solutions","d":"Next-generation firewall supply, configuration and rule-base management.","what":"Next-generation firewall supply and lifecycle — sizing, deployment, rule-base hygiene and continuous management of the perimeter and internal segmentation checkpoints (Sophos XG practice from the flagship portfolio).","scope":[["Sizing & supply",["Throughput and session sizing from real traffic","HA pairs for critical sites","Subscription licensing managed and renewed"]],["Deployment",["Zero-downtime insertion or migration paths","Policy translation from legacy firewalls","VPN mesh for multi-site and remote staff"]],["Rule-base management",["Rule cleanup and shadowing removal","Change control with documented tickets","Periodic policy review"]],["Monitoring",["Log retention and alerting","Monthly usage and threat reports","Coordinated response with cloud security layer"]]],"process":[["1 · Baseline","Traffic flows, applications and risk appetite documented"],["2 · Deploy","Policy built clean — not migrated stale; cutover with rollback"],["3 · Manage","Rule-base under change control; health and threat reporting per period"]],"faq":[["Can you take over an existing firewall we didn''t buy from you?","Yes — takeover starts with a rule-base audit; cleanup findings come before any upsizing recommendation."],["What happens when the subscription expires?","Renewals are tracked by our desk and flagged 60 days ahead — lapse-driven outages are a solved problem."]],"related":["network-security","cloud-security"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','cloud-security','en','{"id":"cloud-security","icon":"☁️","t":"Cloud Security Solutions","d":"Identity, mail and endpoint protection delivered from the cloud.","what":"Threat detection, identity & access management, encryption and compliance management with 24/7 security operations against ransomware, phishing and DDoS — the cloud-delivered layer that protects users wherever they work.","scope":[["Identity & access",["MFA rollout and conditional access","SSO across SaaS estate","Privileged access governance"]],["Mail security",["Advanced phishing and impersonation defense","Quarantine workflows users actually follow","DMARC/DKIM/SPF alignment"]],["Endpoint protection",["EDR deployment and tuning","Ransomware rollback readiness","Disk and backup encryption"]],["Compliance & response",["Policy baselines for audits","24/7 monitoring and alert triage","Incident response runbooks"]]],"process":[["1 · Assess","Identity, mail and endpoint exposure tested; quick wins ranked"],["2 · Roll out","MFA and EDR first — the two controls that stop the majority of attacks"],["3 · Operate","24/7 monitoring with monthly incident and posture reports"]],"faq":[["We already have antivirus — is this different?","Yes — ETR/EDR detects behavior, not signatures; paired with MFA it addresses the attacks antivirus misses."],["Who responds at 2 a.m.?","The security operations tier alerts, triages and contains per runbook, with escalation contacts named in the contract."]],"related":["firewall","network-security"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','cabling','en','{"id":"cabling","icon":"🪛","t":"Structured Cabling","d":"Certified copper and fiber structured cabling for offices, warehouses and retail.","what":"Certified cabling infrastructure — copper and fiber designed, installed and label-tested for offices, warehouses and retail floors, with test reports per drop and as-built drawings you can hand to anyone.","scope":[["Design",["Cable counts and pathways from floor plans","Copper Cat6/6A and fiber backbones","Warehouse and retail environment hardening"]],["Installation",["Certified installer crews","Labeling per rack and drop","Patch panel and cabinet standards"]],["Testing",["Fluke-certified test results per outlet","Fiber OTDR results on backbone links","Warranty registration with manufacturer"]],["Documentation",["As-built drawings and port maps","Patch records maintained","Expansion plans annotated"]]],"process":[["1 · Survey","Site walk with floor plans; counts, pathways and containment quoted"],["2 · Install","Phased installation that keeps the business running; daily cleanup"],["3 · Certify & document","Every drop tested, every label matched, as-builts handed over"]],"faq":[["Can you work weekends or after hours?","Yes — phased out-of-hours schedules are standard for occupied offices and live warehouses."],["Do you certify the installation?","Every copper drop is Fluke-tested and fiber runs get OTDR results — reports are part of handover."]],"related":["network-security","infra"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','av','en','{"id":"av","icon":"🎥","t":"AV and Meeting Room Solutions","d":"Conference displays, audio and video conferencing rooms, ready to hybrid work.","what":"Nearity all-in-one conferencing systems, professional displays, audio and control — designed and installed for huddle rooms, boardrooms and conference halls, with the displays and accessories supplied from the same authorized stock.","scope":[["Room design",["Huddle, boardroom and hall sizing","Sight-line and acoustic planning","Standard BYOD vs room-system choices"]],["Conferencing systems",["Nearity all-in-one mic/speaker/camera units","Platform bring-your-own or native room systems","Single-cable and wireless present options"]],["Displays & control",["Professional displays from the catalog","Mounting, power and cable concealment","One-touch room control"]],["Support",["Commissioning and user walkthroughs","Firmware and platform updates","AMC coverage for room hardware"]]],"process":[["1 · Design","Room-by-room use cases and standards agreed — not one-size-fits-all"],["2 · Install","Displays, audio and cabling installed and commissioned off-hours where needed"],["3 · Adopt","User walkthroughs and quick-reference cards; support path to the service desk"]],"faq":[["Which meeting platforms are supported?","The Nearity line works with the major platforms; native room-system variants are quoted per room."],["Can rooms be added one at a time?","Yes — the standard scales per room; pilots often start with one boardroom and one huddle room."]],"related":["infra","support"],"cats":["monitors","accessories"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','telephony','en','{"id":"telephony","icon":"☎️","t":"IP Telephony Solutions","d":"IP PBX, desk phones and SIP trunks replacing legacy telephony.","what":"Replace the legacy PBX with IP telephony — desk phones, soft clients and SIP trunks designed for UAE businesses, with number portability handled and the old system decommissioned cleanly.","scope":[["IP PBX",["On-premise or hosted PBX sizing","Auto-attendant, hunt groups and queues","Integration with CRM/helpdesk where needed"]],["Endpoints",["Desk phones and conference units","Soft clients for remote staff","Headset and accessory kits"]],["Connectivity",["SIP trunk provisioning and number porting","Call routing and failover design","QoS alignment with the network layer"]],["Support",["Moves/adds/changes as a service","Trunk monitoring and alerting","AMC option for the PBX estate"]]],"process":[["1 · Discover","Extensions, call flows and trunk usage mapped from the legacy system"],["2 · Migrate","Parallel running with number porting scheduled to the minute"],["3 · Decommission","Legacy PBX retired; documentation and MAC process handed over"]],"faq":[["Can we keep our existing phone numbers?","Yes — number porting is part of the migration plan, timed to avoid disruption."],["What about staff working from home?","Soft clients register securely from anywhere; the desk phone becomes optional, not mandatory."]],"related":["network-security","managed"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','data-recovery','en','{"id":"data-recovery","icon":"💾","t":"Data Recovery, Storage Solutions","d":"Backup architecture and recovery services built on our storage DNA.","what":"Enterprise data recovery plus storage architecture — NAS, SAN, cloud storage and backup strategy design. Recover data from failed drives and corrupted systems, then design the storage so it never happens twice.","scope":[["Data recovery",["Failed drive and RAID recovery triage","Corrupted filesystem and volume repair","No-recovery, no-fee assessment"]],["Storage architecture",["NAS and SAN design on storage DNA","Capacity, tiering and growth planning","Shared storage for virtualization"]],["Backup strategy",["3-2-1 backup architecture design","RPO/RTO agreed per workload","Immutable / offline copy for ransomware resilience"]],["Recovery assurance",["Restore testing scheduled, not assumed","Disaster-recovery runbooks","Recovery drills with timing evidence"]],["Catalog depth",["SSD and memory tiers from the 78-SKU portfolio","Crucial performance and pro lines","Enterprise drive sourcing"]]],"process":[["1 · Triage","Failed media assessed; recoverability and quote before work starts"],["2 · Recover","Imaging-based recovery in controlled conditions, original media preserved"],["3 · Harden","Findings feed the backup/storage design so the failure mode is closed"]],"faq":[["What are the odds my data is recoverable?","A controlled assessment answers that before you commit — no-recovery, no-fee on the evaluation."],["Do you only recover, or also fix the architecture?","Both — recovery is the emergency; the storage and backup design closes the root cause."]],"related":["infra","cloud-security"],"cats":["internal-ssd","portable-ssd","memory"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','licensing','en','{"id":"licensing","icon":"🧾","t":"Software & Licensing Support","d":"Licensing advisory and deployment support, now extended with Unisoft engineering.","what":"Licensing advisory and deployment support — compliance position mapped, renewals tracked, and since the software business line: deployment engineering from the Unisoft team behind it.","scope":[["Advisory",["License position audits","True-up planning and budget smoothing","Vendor program guidance"]],["Procurement",["Renewal tracking with 60-day flags","Multi-vendor consolidation","License delivery and activation management"]],["Deployment support",["Rollout engineering via the Unisoft practice","Integration with existing estates","Admin training and handover"]],["Compliance",["Audit-readiness evidence packs","Usage vs entitlement reporting","Decommissioning and license reuse"]]],"process":[["1 · Map","Entitlements vs deployments reconciled — the true position, not the assumed one"],["2 · Optimize","Gaps closed, waste reassigned; renewals put on a tracked calendar"],["3 · Support","Deployment engineering and audit-ready reporting on request"]],"faq":[["We were flagged for a vendor audit — can you help?","Yes — the license-position audit produces the evidence pack; remediation options come with it."],["Is this tied to buying licenses from Simal?","No — advisory stands alone; procurement is offered, not required."]],"related":["amc","support"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('it_solution','support','en','{"id":"support","icon":"🔧","t":"Support and Maintenance","d":"Break-fix and consumables logistics with JAFZA-fulfilled spare pools.","what":"Break-fix repair logistics and consumables supply running on JAFZA-fulfilled spare pools — the non-contract sibling of AMC for organizations that need reliable fixes without an annual commitment.","scope":[["Break-fix",["Repair intake and triage via the service desk","Vendor warranty coordination","Advance replacement where available"]],["Spares logistics",["JAFZA-held spare pools for common lines","Same/next business day dispatch in UAE","GCC same-week shipping"]],["Consumables",["Printer and device consumables supply","Stocked min-max per agreement","Scheduled replenishment"]],["Escalation path",["Named desk contacts","Repair status visibility","Path into AMC when volume justifies it"]]],"process":[["1 · Log","Ticket logged with the desk; triage and ETA issued"],["2 · Fix","Repair, RMA or advance-replacement per warranty and stock"],["3 · Report","Repair history per asset — the data that later right-sizes an AMC tier"]],"faq":[["No contract — how is response time handled?","Break-fix runs best-effort with stock-based ETAs; contracted response times are the AMC tier table''s job."],["When does break-fix stop making sense?","When repair frequency crosses a threshold the desk will show you — the data argues for the AMC tier, not the salesperson."]],"related":["amc","licensing"],"cats":[]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','authorized-it-distributors-uae','en','{"slug":"authorized-it-distributors-uae","t":"Why Choose Authorized IT Distributors in UAE — The Hidden Risks of Grey Market Hardware","cat":"CHANNEL","mins":8,"at":"2026-09-18","author":"Simal Desk","tags":["distribution","warranty"],"x":"The GCC grey market is enormous and quiet. What counterfeit accessories, dead warranties and compliance exposure really cost — and seven questions that expose a grey-channel supplier in one call.","body":[["The scale of the problem",["Grey-market IT hardware moves through the GCC in volumes nobody official will quote, because by definition it is untracked: accessories and components sourced outside manufacturer channels, imported through third countries, sold at prices that look 10–15% better than authorized stock.","For accessories the problem is worst of all — cables, hubs, drives and enclosures are easy to counterfeit, hard to verify visually, and carry the highest failure-return rates in the category."]],["The four real risks",["Counterfeit products: the drive arrives in genuine-looking packaging with inferior flash inside. No warranty: the manufacturer honors serials sold through authorized channels only — a grey unit is a unit without a manufacturer behind it. No support: firmware, compatibility and RMA flows all assume channel provenance. Compliance exposure: products imported without proper documentation can impound an entire consignment, not just the grey line items."]],["How to verify an authorized distributor",["Ask for the brand relationship, not a logo on a website. Ask where stock ships from and who signs the RMA. Ask for the DOA policy in writing. An authorized distributor answers in one call; a grey trader changes the subject to price."]],["What Simal brings to this table",["Simal Technologies ME operates authorized distribution across a 21-brand portfolio, fulfills from JAFZA with same/next-business-day UAE delivery, and runs RMA locally through the desk. When we say the unit is covered, there is a manufacturer and a warehouse behind the sentence."]],["Checklist: 7 questions to ask your IT supplier",["1. Which manufacturer relationship covers this exact SKU? 2. Where does my stock physically ship from? 3. Who processes warranty — you or the brand? 4. What is the DOA window in writing? 5. Can you serialize my order for audit? 6. What is your RMA turnaround, measured? 7. What happens if a consignment is held at customs?"]]],"rel":["why-gray-market-costs-more","top-ssds-for-resellers-2025"],"cta":["Verify your stock channel","/contact"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','enterprise-ssd-buying-guide-2026','en','{"slug":"enterprise-ssd-buying-guide-2026","t":"Enterprise SSD Buying Guide 2026 — SAS vs NVMe vs SATA","cat":"GUIDE","mins":12,"at":"2026-09-04","author":"Storage & Components","tags":["storage","guides"],"x":"SATA at 6 Gbps, SAS at 12, NVMe on PCIe 5.0 at four times that again — plus form factors from M.2 to E3.S and endurance measured in drive-writes-per-day. The decision framework we use with data-center buyers.","body":[["Interfaces: the honest comparison",["SATA III caps around 550 MB/s and belongs in cold storage and legacy estates. SAS doubles that and adds dual-port failover that storage arrays still demand. NVMe speaks PCIe directly: Gen4 drives sustain ~7 GB/s, Gen5 parts like the Crucial T705 push past 14 GB/s — bandwidth that only matters for workloads that can use it."]],["Form factors",["2.5-inch U.2/U.3 dominates dense arrays; M.2 2280 is the server-boot and workstation standard; E1.S and E3.S are the hyperscale rulers that trade height for serviceability. Match the form factor to the chassis you will actually run for five years, not the one that photographs well."]],["Endurance: DWPD explained",["Drive-writes-per-day is the number of times you can rewrite the drive''s full capacity daily across the warranty. Read-intensive cache parts run 0.3–1 DWPD; mixed-use virtualization drives 1–3; write-heavy database and journal drives need 3+ or they will die inside the warranty window — politely, without warning, at the worst moment."]],["Workload-optimized selection",["Read-intensive: web serving, analytics scratch, media. Mixed-use: virtualization, general databases. Write-intensive: transaction logs, journals, heavy ingest. The catalog line we stock deepest per tier — Crucial T500/T705 for client and edge, enterprise SATA/SAS lines for arrays — reflects what UAE buyers actually deploy."]],["TCO over five years",["Price per GB is the wrong metric; price per sustained IOPS per year is closer to right. A Gen5 NVMe part at twice the SATA price that delivers eight times the transactions is the cheaper drive for a hot tier — and the wrong buy for an archive tier. Tier the storage, then pick the interface per tier."]]],"rel":["top-ssds-for-resellers-2025","ddr4-vs-ddr5"],"cta":["Spec your storage tiers","/products#internal-ssd"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','unierp-transforms-sme','en','{"slug":"unierp-transforms-sme","t":"How UniERP Transforms SME Operations — A Real-World Implementation Story","cat":"SOFTWARE","mins":10,"at":"2026-08-21","author":"Software Practice","tags":["erp","unierp"],"x":"Fourteen spreadsheets, three disconnected systems, 75 employees — and a 14-week phased go-live. The implementation story the content team tells prospects, with the lessons the client would repeat and the ones they wouldn''t.","body":[["Before: the spreadsheet era",["The company ran 14 Excel sheets across three disconnected systems — sales orders in one, inventory in another, finance reconciling both at month-end. Seventy-five employees, real revenue, and no single number anyone trusted without a meeting."]],["Why UniERP over SAP Business One and Zoho",["The shortlist came down to per-user economics, data ownership and regional support. SAP B1 priced per user into a five-figure annual commitment for a 75-seat company; Zoho rented well but raised data-portability and customization-ceiling questions. UniERP on Odoo 19 Community Edition carries $0 per-user licensing, source access, and a Dubai desk with a Dhaka engineering team behind it."]],["The 14-week journey",["Weeks 1–3 discovery and process mapping; weeks 4–10 phased configuration and data migration with parallel running; weeks 11–14 go-live by module — inventory first, then sales, then finance close. No big-bang cutover; every phase ran beside the old process until the numbers agreed."]],["The results",["Admin costs down 40% as reconciliation work disappeared. Real-time inventory visibility ended the stock-out surprise. Monthly close moved from days of spreadsheet archaeology to hours — 60% faster with audit trail attached to every entry."]],["Lessons the client would underline",["Clean your master data before migration, not during. Put finance in the discovery room from day one. And appoint an internal owner with authority — the phases that slipped were the phases where nobody owned the decision."]]],"rel":["ai-in-erp-2026","industry-4-manufacturing-erp"],"cta":["See UniERP live","software-erp.html"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','uae-data-protection-pdpl','en','{"slug":"uae-data-protection-pdpl","t":"UAE Data Protection Law & Your IT Infrastructure — Are You Compliant?","cat":"COMPLIANCE","mins":9,"at":"2026-08-07","author":"Security Desk","tags":["pdpl","compliance"],"x":"Federal Decree-Law No. 45 of 2021 (PDPL) sets the obligations — consent, minimization, breach notification, cross-border transfer. Here is what each one means for the infrastructure you actually run.","body":[["What PDPL actually requires",["Consent for processing personal data beyond defined lawful bases. Data minimization — collect what the purpose requires, not what the form was already asking. Breach notification within defined timelines to the UAE data office and affected individuals. Cross-border transfer controls: personal data leaves the country only under adequate-protection conditions."]],["Where your data lives is now a design decision",["Every SaaS subscription is a cross-border transfer question. Every shared drive is an access-control question. The infrastructure map — what data, on which systems, under whose access, in which jurisdiction — is the first artifact a PDPL review asks for, and most companies cannot produce one."]],["The technical controls that answer the law",["Encryption at rest and in transit for personal data stores. Role-based access with joiner-mover-leaver discipline. Audit logging on systems holding personal data — the trail that proves what happened. Backup with a tested restore, because availability obligations are part of the picture."]],["A 10-point readiness assessment",["1. Data inventory by system and jurisdiction. 2. Lawful basis mapped per processing activity. 3. Consent mechanism real and logged. 4. Retention schedule exists. 5. Access reviews scheduled. 6. Encryption posture verified. 7. Breach notification runbook written. 8. Vendor/processor agreements reviewed. 9. Cross-border transfers catalogued. 10. An accountable owner named. Score under 7 and you have your project list."]]],"rel":["cybersecurity-best-practices-uae","peppol-in-90-days"],"cta":["Book a PDPL readiness review","/contact"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','ddr4-vs-ddr5','en','{"slug":"ddr4-vs-ddr5","t":"DDR4 vs DDR5 — What Businesses Need to Know Before Upgrading","cat":"GUIDE","mins":7,"at":"2026-07-24","author":"Storage & Components","tags":["memory","guides"],"x":"Higher clocks, lower voltage, bigger capacity per module — and a platform decision you cannot undo for three years. When the DDR5 premium pays and when DDR4 remains the sober choice.","body":[["The technical delta",["DDR5 starts where DDR4 tops out: entry modules run 4800 MT/s against DDR4''s 3200, with 5600–6400 parts standard in the channel now. Voltage drops from 1.2 V to 1.1 V. On-module power management moves voltage regulation off the motherboard. Capacity per module doubles — 32 GB and 48 GB DIMMs are routine where DDR4 practical ceilings sat at 32 GB."]],["Real-world workloads",["Office productivity: indistinguishable. Virtualization and databases: capacity and bandwidth pay visibly. AI inference workstations: memory bandwidth is frequently the binding constraint, and DDR5 is simply the correct platform. The laptops and mini-PCs we ship fastest in 2026 are DDR5 not because of benchmarks but because 32 GB+ configurations are cheaper to reach."]],["Compatibility — the part that bites",["DDR5 requires a DDR5 platform: CPU and chipset both. You cannot stage a memory upgrade into a DDR4 fleet; it is a platform refresh decision. That makes the honest question not \"DDR5 or DDR4\" but \"is this machine due for replacement anyway?\""]],["Cost over three years",["Price per GB has converged hard; the DDR5 premium now lives mostly in the platform, not the modules. For fleets, the arithmetic that matters: DDR4 stock on a retiring platform is stranded spend; DDR5 on a 3-year platform is aligned spend. When DDR4 is still right: budget-repair of machines that will not survive to the next refresh anyway."]]],"rel":["enterprise-ssd-buying-guide-2026","future-proof-it-infrastructure"],"cta":["Price a DDR5 refresh","/products#memory"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','ai-in-erp-2026','en','{"slug":"ai-in-erp-2026","t":"The Rise of AI in ERP Systems — Hype vs. Reality in 2026","cat":"SOFTWARE","mins":11,"at":"2026-07-10","author":"Software Practice","tags":["ai","erp"],"x":"Document processing, demand forecasting and anomaly detection ship today and pay. Autonomous decision-making and natural-language ERP remain demos. A framework for separating the two in any vendor pitch.","body":[["What \"AI in ERP\" means today",["Three things that work: document processing that reads invoices and receipts into structured records; demand forecasting that learns seasonality from your own transaction history; anomaly detection that flags the duplicate payment and the supplier whose prices drifted. Everything else on the slide is a roadmap item with a font upgrade."]],["Proven use cases, honestly costed",["Invoice capture removes keying labor and its error rate — measurable in hours and exception counts per month. Forecasting shows up as stock-turn and availability improvements over 2–3 cycles, not overnight. Anomaly detection earns its keep the first time it catches a payment run twice. None of them require a data-science team on staff; they require clean transaction history, which your ERP already has."]],["Still experimental — treat as such",["Autonomous decision-making (letting the system approve or order without a human) fails audits and occasionally suppliers. Natural-language querying of ledgers demos beautifully and hallucinates numbers under load. If a vendor leads with these, ask what shipped, to how many customers, with what measured result."]],["UniERP''s position",["The UniERP roadmap ships the working three: document flows into finance, forecasting into inventory replenishment, anomaly flags into approvals. AI features arrive on the Odoo 19 CE core at $0 per-user licensing — the AI line item should be services, never a license multiplier."]],["How to evaluate any AI claim",["Ask for the training data (it should be your history, not a generic model). Ask for the failure mode and the human override. Ask which metric moves and over what period. Vendors with real features answer in specifics; vendors with roadmaps answer in adjectives."]]],"rel":["unierp-transforms-sme","industry-4-manufacturing-erp"],"cta":["Scope the working AI trio","/software#solutions"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','cybersecurity-best-practices-uae','en','{"slug":"cybersecurity-best-practices-uae","t":"Cybersecurity Best Practices for UAE Businesses — A Practical Guide","cat":"SECURITY","mins":10,"at":"2026-06-26","author":"Security Desk","tags":["security","uae"],"x":"Ransomware, phishing and supply-chain attacks against UAE firms — and the short list of controls that stop the majority of incidents: MFA, endpoint protection, segmentation, tested backup.","body":[["The 2026 threat landscape, unsensationally",["Ransomware remains the headline risk because it stops revenue, not just IT. Phishing is the entry door for most of it. Supply-chain attacks — compromise of a vendor or update channel — are the growth category, and they hit companies with perfect perimeter hygiene through someone else''s laptop."]],["The essential controls, in order",["MFA on email, VPN and admin accounts — the single control that kills the majority of account-takeover paths. Endpoint detection and response on every device, tuned rather than installed-and-forgotten. Network segmentation so one compromised VLAN is not the whole company. Backup that is tested, offline or immutable — ransomware negotiates badly with a restore."]],["UAE-specific considerations",["NESA/IAS standards apply to critical infrastructure and government-adjacent work; PDPL sets personal-data obligations regardless of sector; free-zone and sector regulators add their own overlays. The practical effect: your control set must be documentable, not just effective — evidence is part of compliance."]],["The first 60 minutes of a breach",["Isolate affected systems (network cut, not shutdown — memory evidence matters). Activate the incident runbook with the named contact tree. Preserve logs. Notify per your regulatory and contractual obligations — timelines are short and runbooks written during the incident always miss one."]],["Building the culture",["Quarterly phishing exercises with coaching instead of shame. Access reviews tied to joiner-mover-leaver. A reported-phono-number users actually know. The desk sees the difference: organizations that drill recover in hours; organizations that don''t, in weeks."]]],"rel":["uae-data-protection-pdpl","future-proof-it-infrastructure"],"cta":["Book a security baseline review","/solutions/cloud-security/"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','future-proof-it-infrastructure','en','{"slug":"future-proof-it-infrastructure","t":"How to Build a Future-Proof IT Infrastructure — Scalability, Security & Cost","cat":"GUIDE","mins":8,"at":"2026-06-12","author":"Simal Desk","tags":["infrastructure","guides"],"x":"Modular, standards-based, cloud-ready — and sized against a refresh calendar instead of a wish. The design principles plus the buy-timing math we run with UAE IT managers.","body":[["Principles that survive contact with budgets",["Modularity: buy units you can extend, not monoliths you must replace. Standards-based: the boring interface outlives the clever one every time. Cloud-ready: identity, backup and monitoring designed to span premises and cloud even if today you run none."]],["Hardware strategy without religion",["Enterprise for shared services and anything with an uptime promise. Business-class for fleets where management features pay. Consumer for nothing that touches company data. Hyperscale economics belong to hyperscalers; a mid-size UAE firm buying that way buys complexity, not savings."]],["What belongs where",["On-premise: latency-sensitive systems, data with residency constraints, workloads with predictable dense load. Cloud: bursty workloads, collaboration, DR for the systems that cannot wait for a truck. The interesting decisions are the middle — run them on total cost over three years, not on which department asked first."]],["Lifecycle management",["Refresh cycles: laptops 3–4 years, servers 4–5, network 5–7 — stretched, never ignored, because the failure curve and the security-support curve both bend up at the end. Capacity planning against the asset register you keep anyway. Obsolescence tracked as a calendar, not a surprise."]],["Budgeting honestly",["Model CAPEX vs OPEX per workload over three years including the people-cost of each. Provision for the peak you can prove, not the peak you can imagine — over-provisioning is the most common way mid-size infrastructure burns money quietly."]]],"rel":["ddr4-vs-ddr5","cybersecurity-best-practices-uae"],"cta":["Design your next refresh","/solutions"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','industry-4-manufacturing-erp','en','{"slug":"industry-4-manufacturing-erp","t":"Industry 4.0 — Manufacturing ERP Trends Transforming GCC Factories","cat":"SOFTWARE","mins":9,"at":"2026-05-29","author":"Software Practice","tags":["manufacturing","erp"],"x":"Saudi Vision 2030, UAE Operation 300bn, Oman Vision 2040 — the national programs pushing GCC factories toward IoT sensing, digital twins and AI inspection, with the ERP as the backbone that binds them.","body":[["The policy tailwind",["GCC industrial strategies are not subtle: localization targets, technology-adoption incentives, and funding programs that reward measurable digitization. For factory operators this changes the ROI math — a shop-floor data project that was nice-to-have now offsets against program benefits and customer-scorecard requirements."]],["The technologies that are actually deploying",["IoT sensing on lines and utilities — the data layer everything else needs. Digital twins for layout and throughput simulation before capital is committed. AI quality inspection on vision systems that flag defects faster than humans and never tire. Predictive maintenance that converts downtime calendars into condition-based service."]],["The ERP as the digital backbone",["Sensors without a system of record are telemetry in search of a decision. Industry 4.0 pays when machine events flow into the same core as orders, inventory and finance: the defect trend informs the supplier scorecard, the energy curve informs the cost sheet, the maintenance prediction schedules around the production plan."]],["What ROI looks like in practice",["The pattern from GCC adopters: OEE gains from addressing the bottlenecks sensing exposes; quality-cost reductions from catching defects in-line rather than at final inspection; maintenance savings from fixing bearings before they fail. The common thread is that the first wins come from visibility, not automation — you act on data you finally have."]],["How UniERP fits",["On the Odoo 19 CE core: manufacturing and inventory modules with shop-floor tracking, IoT integration hooks, and analytics on the same ledger as finance. The Industry-4.0 journey starts with the backbone — $0 per-user licensing keeps the sensor budget where it should be, on the floor."]]],"rel":["ai-in-erp-2026","unierp-transforms-sme"],"cta":["Tour the manufacturing modules","/software#solutions"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','simal-two-decades','en','{"slug":"simal-two-decades","t":"Simal Technologies: Two Decades of IT Distribution in the Middle East","cat":"COMPANY","mins":6,"at":"2026-05-15","author":"Simal Desk","tags":["company","story"],"x":"From a Bur Dubai trading office in 2002 to an authorized 21-brand distribution house with a JAFZA warehouse, a Kyiv-trained logistics habit and — in 2026 — a software business line. The short version of a long story.","body":[["The founding years",["Simal Technologies started in 2002 in Bur Dubai — a trading office moving components in a market where relationships were the entire infrastructure. The early lesson that stuck: your word is your warehouse credit."]],["Milestones that mattered",["The first manufacturer authorization — the moment a brand put its name next to ours. The JAFZA warehouse operation that turned availability from a promise into a logistics fact. Growth of the authorized portfolio to 21 brands — Crucial, Hikvision, TeamGroup, UGREEN among them. And 2026: the launch of the software business line with Unisoft Systems, extending distribution logic into solutions."]],["The Simal–Unisoft partnership",["Simal runs distribution daily in the UAE; Unisoft Systems in Dhaka has spent years building and implementing the software that runs businesses — 40+ engineers, ISO 9001/27001 discipline. The software line positions it plainly: Simal''s software solution services, engineered with Unisoft. Regional presence and sales from Dubai; engineering depth from Dhaka."]],["What we optimize for",["Reliability over spectacle: genuine stock, documented warranty, RMA that answers. Partnership over transaction: the reseller who grows with us gets territory respect, not just volume pricing. And now — solutions over boxes: the same desk that ships drives can scope your ERP."]],["Where this goes",["More brands where they deepen the portfolio, the software line into its first UAE rollouts, and the same bias we have run since 2002: answer the phone, ship the stock, keep the records clean."]]],"rel":["authorized-it-distributors-uae","unierp-transforms-sme"],"cta":["Work with the desk","/about"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','top-ssds-for-resellers-2025','en','{"slug":"top-ssds-for-resellers-2025","t":"Top SSDs for Resellers in 2025→2026","cat":"STORAGE","mins":6,"at":"2026-04-30","author":"Storage & Components","tags":["storage","channel"],"x":"The Gen5 era is here: what Crucial T705, P510 and T500 mean for channel margins and stock planning in the UAE.","body":[["What we ship weekly says where margins are going",["Gen5 drives are moving from enthusiast to mainstream builds, 27″ high-refresh panels became the default gaming SKU, and ruggedized portable SSDs are eating the external-HDD basket. Resellers who bundle drive + enclosure + hub in one RFQ are winning the accessory attach."]],["The three Crucial lines and their lanes",["T705: the Gen5 flagship for creators and workstations where 14 GB/s is a workflow, not a stat. P510: mainstream Gen5 at Gen4 pricing — the volume play this cycle. T500: the Gen4 workhorse that still wins on price-performance for the majority of builds. Stock depth per lane beats breadth across brands."]],["The attach strategy",["The margin on the drive is honest but thin; the bundle is where the RFQ grows — enclosures, docks, hubs, memory to feed the platform. One basket, one warranty channel, one delivery. It is the oldest retail insight, applied to B2B."]]],"rel":["crucial-p510-launch","enterprise-ssd-buying-guide-2026"],"cta":["Check channel stock","/products#internal-ssd"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','crucial-p510-launch','en','{"slug":"crucial-p510-launch","t":"Crucial P510 Lands in Dubai","cat":"PRODUCT","mins":4,"at":"2026-04-16","author":"Storage & Components","tags":["product","storage"],"x":"Mainstream Gen5 performance at Gen4 pricing — first impressions and channel availability from Simal stock.","body":[["First impressions",["The P510 is the drive that makes Gen5 a default rather than an upsell: sequential rates comfortably beyond Gen4 ceilings, at price points that close the argument for new-build platforms. For system integrators it simplifies the quote — one less line to defend."]],["Channel availability",["Stock landed in Dubai and the announcement went out over the desk: the P510 is in JAFZA inventory with same/next-business-day UAE delivery and RFQ channel pricing. Genuine units, serialized, warranty through the manufacturer — the unremarkable machinery of authorized distribution doing its job."]],["Who should quote it",["New workstation and gaming builds on current platforms; anyone whose customer asked for Gen5 last quarter and flinched at flagship pricing. The T705 keeps the no-compromise lane; the P510 takes the volume."]]],"rel":["top-ssds-for-resellers-2025","ddr4-vs-ddr5"],"cta":["RFQ the P510","/products/crucial-p510-nvme-ssd"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','peppol-in-90-days','en','{"slug":"peppol-in-90-days","t":"Peppol in 90 Days — a Reseller Checklist","cat":"COMPLIANCE","mins":7,"at":"2026-04-02","author":"Simal Desk","tags":["peppol","e-invoicing"],"x":"UAE e-invoicing Phase 1 lands 1 January 2027. TRN formats, ASP choice, and the three fields your PO system must emit — the 90-day working-backward plan.","body":[["The mandate, plainly",["The UAE FTA e-invoicing program goes live in phases from 1 January 2027 — structured electronic invoicing through Peppol-network exchange, with TRN-based addressing (the 0235 prefix) identifying each trading party. For resellers and their enterprise customers this is not a portal to log into; it is a document format your systems must emit and consume."]],["What actually changes in your stack",["Three fields decide your readiness: buyer and seller identification in Peppol format on every invoice, line-level structured data instead of PDF attachments, and the interchange metadata the network validates. If your PO and invoicing flow cannot emit these, that is the project."]],["Choosing an ASP",["An accredited Peppol access point becomes your post office. Choose on: accreditation status, UAE support hours, integration path from your actual ERP — and pricing that is per-document, not per-mystery. The desk will publish a shortlist as accreditations land."]],["The 90-day countdown",["Days 90–61: inventory your invoice flows in and out; confirm your TRN registrations per entity. Days 60–31: select the ASP; pilot structured invoices with two friendly counterparties. Days 30–0: parallel-run both formats, reconcile, then switch the compliant flow live — before the mandate, not after the penalty."]],["Where UniVAT fits",["The UniVAT line carries Peppol-ready tooling born from NBR-approved government integration — one of five systems so approved in Bangladesh. The Dhaka-to-Dubai compliance discipline transfers; the 2027 switch-on becomes configuration, not construction."]]],"rel":["uae-data-protection-pdpl","unierp-transforms-sme"],"cta":["Start your Peppol countdown","/software#solutions"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
INSERT INTO content_blocks (entity,entity_id,lang,payload) VALUES ('insight','why-gray-market-costs-more','en','{"slug":"why-gray-market-costs-more","t":"Why Gray-Market Accessories Cost More","cat":"CHANNEL","mins":4,"at":"2026-03-19","author":"Simal Desk","tags":["channel","warranty"],"x":"A RMA math exercise: save 12% upfront, pay 3× in failed units and warranty fights.","body":[["The upfront arithmetic",["The gray-market accessory quotes 12% under authorized stock. On a 500-unit accessories order that difference looks like a month of coffee for the office — visible, immediate, seductive."]],["The failure arithmetic",["Field failure rates on gray accessories run multiples of authorized stock — counterfeit flash and cable batches dominate the returns story. At 3× the failure rate, the 12% saving becomes a 20%+ effective premium once replacements, re-visits and customer goodwill enter the ledger."]],["The warranty fight nobody budgets",["A gray unit has no manufacturer behind it: no serial entitlement, no advance replacement, no firmware support. Every failed unit becomes a negotiation with the trader who sold it — whose incentive structure is not difficult to imagine."]],["The channel answer",["Authorized distribution prices the failure rate and the warranty into the unit: genuine stock, local RMA through the desk, advance replacement where warranty allows. The premium is not margin — it is the absence of the 3× tail."]]],"rel":["authorized-it-distributors-uae","crucial-p510-launch"],"cta":["Compare the real cost","/contact"]}') ON CONFLICT (entity,entity_id,lang) DO NOTHING;
