INSERT INTO testimonials (id, quote, name, role, company, active)
VALUES
  (1, 'We have been working with Simal Technologies for quite some time now, and our overall experience has been excellent. The quality of the IT products we’ve received has consistently met our expectations.', 'Jasper Guevarra', 'Technical Support Manager', 'Mercans', TRUE),
  (2, 'My overall experience with Simal Technologies was great! The team was responsive and provided excellent customer service throughout. I really liked how knowledgeable and helpful they were.', 'Nadeem', 'Sales Manager', 'Microtrans LLC', TRUE),
  (3, 'I have been dealing with your salesman Hassan Musheer, and he was well-behaved and very responsive. Your pricing is also excellent, and deliveries are managed efficiently.', 'Muhammad Jaseem', 'Purchase Executive', 'Grand PCD Trading LLC', TRUE)
